const MN=['jan','feb','mar','apr','maj','jun','jul','avg','sep','okt','nov','dec'];
function mIso(x){if(!x)return null;if(/^\d{4}-\d{2}$/.test(x))return x;const m=String(x).match(/^([a-zč]{3})\w*\s+(\d{2,4})$/i);if(!m)return null;const mi=MN.indexOf(m[1].toLowerCase());if(mi<0)return null;const y=m[2].length===2?'20'+m[2]:m[2];return y+'-'+String(mi+1).padStart(2,'0')}
function mLab(x){const i=mIso(x);if(!i)return String(x||'');return MN[+i.slice(5)-1]+' '+i.slice(0,4)}
const MF=['januar','februar','marec','april','maj','junij','julij','avgust','september','oktober','november','december'];
function mFull(x){const i=mIso(x);if(i)return MF[+i.slice(5)-1]+' '+i.slice(0,4);return String(x||'')}
function mNext(iso){let y=+iso.slice(0,4),m=+iso.slice(5)+1;if(m>12){m=1;y++}return y+'-'+String(m).padStart(2,'0')}
function nowIso(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}
function openM(st,months){if(st&&st.m)return st.m;const last=(months||[]).map(mIso).filter(Boolean).pop();return last?mNext(last):nowIso()}
function curM(){if(!SITST.m)SITST.m=openM(SITST,MONTHS);return mLab(SITST.m)}
function curShort(){return curM()}
function canFin(o){return S.role!=='nejc'||o.vodja===ME}
