const FOLD={'02':'Ponudbe','03':'Pogodba','04':'Načrti','05':'Izjave','06':'Dobavitelji','07':'Dopisi','08':'Fotografije','09':'Situacije','10':'Primopredaja in garancija','11':'Korespondenca','12':'Zapisniki','13':'Naročilnice','14':'Menice, izvršnice, bančne garancije in zavarovanja','15':'Izvajalske pogodbe','16':'Podizvajalci','17':'Gradbena knjiga'};const FORD=()=>Object.keys(FOLD).sort((a,b)=>FOLD[a].localeCompare(FOLD[b],'sl'));const fN=id=>{const k=FORD().indexOf(id);return k<0?id:String(k+1).padStart(2,'0')};const fL=id=>fN(id)+' '+(FOLD[id]||'');
