async function delS(fo,n){if(!await uiConfirm('Izbrišem datoteko '+n+'?'))return;DOCHID.push(CUR+'|'+fo+'|'+n);log('Dokumenti','izbrisana '+n);save();render()}
async function delF(id){const m=FILES.find(x=>x.id===id);const nd=DOBA.filter(x=>x.fid===id).length;if(!m||!await uiConfirm('Izbrišem datoteko '+m.name+'?'+(nd?' Odstrani se tudi iz materiala v Stroških.':'')))return;FILES=FILES.filter(x=>x.id!==id);if(nd)DOBA=DOBA.filter(x=>x.fid!==id);fDel(id);log('Dokumenti','izbrisana '+m.name);render()}
async function scanDobav(buf,name,fid){let t='';try{if(window.pdfjsLib){if(!window.pdfjsWorker)pdfjsLib.GlobalWorkerOptions.workerSrc='vendor/pdf.worker.min.js';const doc=await pdfjsLib.getDocument({data:new Uint8Array(buf.slice(0))}).promise;for(let p=1;p<=Math.min(doc.numPages,10);p++){const c=await (await doc.getPage(p)).getTextContent();t+=' '+c.items.map(x=>x.str).join(' ')}}}catch(x){}t=t.replace(/\s+/g,' ');
 const amt=(re)=>{const m=t.match(re);return m?num(m[1]):null};let zn=amt(/(?:skupaj\s*(?:eur\s*)?brez\s*ddv|osnova\s*za\s*ddv|vrednost\s*brez\s*ddv)\s*[:€]?\s*([\d.]+,\d{2})/i);if(zn==null)zn=amt(/(?:za\s*plačilo|skupaj\s*eur|skupaj)\s*[:€]?\s*([\d.]+,\d{2})/i);
 const dob=(t.match(/([A-ZČŠŽ][A-ZČŠŽa-zčšž0-9 .&-]{2,40}?\s(?:d\.\s?o\.\s?o\.|d\.\s?d\.|s\.\s?p\.))/)||[])[1];const st=(t.match(/(?:dobavnica|račun|ponudba)\s*(?:št\.?)?\s*:?\s*([A-Z0-9][\w\-/]*\d[\w\-/]*)/i)||[])[1];const dat=(t.match(/(\d{1,2}\.\s?\d{1,2}\.\s?\d{4})/)||[])[1];
 DOBA.unshift({dob:dob&&!/ŠKERJANEC/i.test(dob)?dob.trim().replace(/^(za|pri|od)\s+/i,''):(t.match(/KALCER/i)?'Kalcer d.o.o.':'dobavitelj'),st:st||name.replace(/\.pdf$/i,''),datum:dat||fd(new Date().toISOString().slice(0,10)),opis:'iz PDF: '+name,zn,fid});log('Material, '+CO().name,'dobavnica '+(st||name)+(zn!=null?' '+e(zn)+' €':' brez prebranega zneska'));toast(zn!=null?'Dobavnica dodana v Stroške: '+e(zn)+' €':'Dobavnica dodana, zneska ni bilo mogoče prebrati')}
async function scanContract(buf,name){try{if(!window.pdfjsLib)return;if(!window.pdfjsWorker)pdfjsLib.GlobalWorkerOptions.workerSrc='vendor/pdf.worker.min.js';const doc=await pdfjsLib.getDocument({data:new Uint8Array(buf.slice(0))}).promise;let t='';for(let p=1;p<=Math.min(doc.numPages,30);p++){const c=await (await doc.getPage(p)).getTextContent();t+=' '+c.items.map(x=>x.str).join(' ')}t=t.replace(/\s+/g,' ');
 const sug={};let m=t.match(/zadrž\w*[^.%]{0,120}?(\d{1,2}(?:[,.]\d)?)\s*%/i)||t.match(/(\d{1,2}(?:[,.]\d)?)\s*%[^.]{0,80}?zadrž/i);if(m)sug.zadrzek=num(m[1]);
 m=t.match(/garancij\w*[^.]{0,80}?(\d{1,2})\s*(?:\(\w+\)\s*)?(let|leti|leta|mesec\w*)/i);if(m)sug.garLet=/mesec/i.test(m[2])?Math.round(+m[1]/12*10)/10:+m[1];
 m=t.match(/(?:v roku|rok plačila\w*|plačilo\w*[^.]{0,40}?v)\s*(\d{2,3})\s*dn/i);if(m)sug.rokPlac=+m[1];
 m=t.match(/avans\w*[^.%]{0,60}?(\d{1,2})\s*%/i);if(m)sug.avans=+m[1];
 const NM='([A-ZČŠŽĆĐ][a-zčšžćđ]+(?:\\s+[A-ZČŠŽĆĐ][a-zčšžćđ]+){1,2})';const ud={os:{}};
 const pats={vg:/(?:odgovorni\s+)?vodja\s+(?:gradnje|gradbišča|del)/i,vp:/vodja\s+projekta/i,dv:/delovodj\w*/i,ar:/(?:odgovorni\s+)?(?:arhitekt\w*|projektant\w*)/i};
 Object.entries(pats).forEach(([k,re])=>{const mm=t.match(new RegExp(re.source+'[^A-ZČŠŽ]{0,40}?'+NM,'i'));if(mm){let after=t.slice(mm.index+mm[0].length,mm.index+mm[0].length+140);const cut=after.search(/(?:^|\s)(?:odgovorni\s+)?(?:vodja|delovodj|projektant|arhitekt|\d+\.\s*člen|naročnik|izvajalec)/i);if(cut>=0)after=after.slice(0,cut);const em=after.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/);const ph=after.match(/(?:\+386|0)[\d\s\/-]{7,14}\d/);if(!/Škerjanec|Skerjanec/i.test(mm[1]))ud.os[k]={ime:mm[1].trim(),tel:ph?ph[0].trim():'',mail:em?em[0]:''}}});
 let iz=t.match(/izvajalec\s*:?\s*([A-ZČŠŽ][^,;:]{2,70}?\b(?:d\.\s?o\.\s?o\.|d\.\s?d\.|s\.\s?p\.))/i);if(iz&&/Škerjanec|Skerjanec/i.test(iz[1]))iz=t.match(/naročnik\s*:?\s*([A-ZČŠŽ][^,;:]{2,70}?\b(?:d\.\s?o\.\s?o\.|d\.\s?d\.|s\.\s?p\.))/i);if(iz)ud.izv=iz[1].trim();
 if(ud.izv||Object.keys(ud.os).length)OBJ[S.obj].sugUd={...ud,src:name};
 if(Object.keys(sug).length)OBJ[S.obj].sug={...sug,src:name};if(Object.keys(sug).length||OBJ[S.obj].sugUd){render();toast('V dokumentu sem našel podatke, preveri in potrdi v Pregledu')}}catch(x){}}
function pogSet(k,v){const o=OBJ[S.obj];o.pog=o.pog||{};o.pog[k]=k==='garancija'||k==='opomba'?v:num(v);log('Pogodba, '+o.name,k+' → '+v);render()}
