function udTxt(p){if(!p)return '';if(p.txt!=null)return p.txt;return [p.ime,p.tel,p.mail].filter(Boolean).join(', ')}
function udMail(p){const m=udTxt(p).match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)+/);return m?m[0]:''}
function udName(p){return (udTxt(p).split(',')[0]||'').trim()}
function udList(o){const u=(o.ud||{}).os||{};return UDR.filter(([k])=>udName(u[k])).map(([k,l])=>`<div style="margin-bottom:8px"><b>${udName(u[k])}</b><div class="muted">${l.toLowerCase()}${udMail(u[k])?' · '+udMail(u[k]):''}</div></div>`).join('')}
