const KCEN=[['Montaža gips stropa','m²','10,00'],['Stena W111','m²','10,00'],['Stena W112','m²','15–17'],['Stena W115 in W116','m²','20,00'],['Gips obloga','m²','8,50'],['Gips obloga z izolacijo','m²','9,50'],['Armstrong Board','m²','9,00'],['Armstrong Microlook','m²','10,00'],['Mansarda z izolacijo do 25 cm in parno zaporo','m²','23,00'],['Dampa, kovinski stropovi','m²','16,00'],['Režijska ura','h','18,00'],['Lepljenje gips plošč','m²','9,00'],['Dodatek za kaskade','m¹','10,00'],['Bandažiranje Q2','m²','3,0–3,5'],['Vogalniki','kos','3,0–3,5'],['Vgradni podboj Knauf','kos','28,50'],['Revizijska vratca','kos','15,00'],['Obdelava strešnih oken','kos','50,00'],['Kaseta za drsna vrata','kos','40,00']];
function podiObj(p){if(!p.plan)return [];const out=new Set();['own','koop'].forEach(g=>PLAN[g].forEach(r=>{if(r.n.split(' · ')[0]===p.plan)r.c.forEach(v=>cCodes(v).forEach(c=>{const o=Object.values(OBJ).find(x=>x.code===c);if(o)out.add(o.name)}))}));return [...out]}
function podiSet(i,k,v){PODI[i][k]=k==='ekipa'?num(v):v;log('Podizvajalci',PODI[i].naziv+': '+k);render()}
async function podiAdd(){const n=await uiPrompt('Naziv podizvajalca (npr. Janez Kranjc s.p.):');if(!n||!n.trim())return;PODI.push({id:'p'+Date.now().toString(36),naziv:n.trim(),plan:'',kontakt:'',ekipa:1,sistemi:'',cene:[]});log('Podizvajalci','dodan '+n);render()}
