function podiKoop(p){const out=[];Object.values(OBJ).filter(o=>o.full&&canSee(o)).forEach(o=>{const d=o.id===CUR?{KOOP}:(o.d||{});(d.KOOP||[]).forEach(k=>{if(k.p===p.id||k.k===p.naziv||(p.plan&&k.k===p.plan))out.push({...k,obj:o.name})})});return out}
function podiAll(p){if(!p)return '';const L=podiKoop(p);const sum=L.reduce((a,k)=>a+(+k.zn||0),0);return `<h2>Vsi obračuni · ${p.naziv}</h2><div class="panel mb"><div class="tw"><table class="t"><thead><tr><th>Objekt</th><th>Obdobje</th><th>Sistem</th><th class="n">Po obračunu</th></tr></thead><tbody>${L.length?L.map(k=>`<tr><td>${k.obj}</td><td>${mFull(k.m)}</td><td>${k.sis||'Suhomontažna dela'}</td><td class="n">${e(k.zn)}</td></tr>`).join(''):'<tr><td colspan="4" class="muted">Za tega podizvajalca še ni obračunov.</td></tr>'}<tr class="sum"><td>Skupaj</td><td></td><td></td><td class="n">${e(sum)}</td></tr></tbody></table></div><div class="pad" style="padding-top:0"><button class="sm" onclick="S.kfil=null;render()">Zapri</button></div></div>`}
function koopForm(pid){S.kf={pid,lines:[]};const has=SIT.some(r=>+r[6])||DOD.some(r=>r[6]==='potrjeno'&&+r[5]);if(has){kfFromSit(false)}else{S.kf.lines=[{opis:'',em:'m²',cena:0,q:0}];render()}}
function kPrice(opis,p){const t=String(opis).toLowerCase();const last=KOOP.find(k=>k.p===p.id&&k.lines);if(last){const hit=last.lines.find(l=>String(l.opis).toLowerCase()===t||String(l.opis).toLowerCase().endsWith(t));if(hit&&hit.cena)return hit.cena}const own=(p.cene||[]).find(c=>{const w=(c[0].match(/W\d{3}/)||c[0].match(/[A-Za-zčšžČŠŽ]{5,}/)||[''])[0].toLowerCase();return w&&t.includes(w.slice(0,6))});if(own)return own[2];if(/w11[56]/.test(t))return 20;if(/w112/.test(t))return 16;if(/w111/.test(t))return 10;if(/mansard/.test(t))return 23;if(/oblog/.test(t))return 8.5;if(/strop/.test(t))return 10;if(/armstrong|kcs|board/.test(t))return 9;return 0}
function kfFromSit(all){const p=PODI.find(x=>x.id===S.kf.pid);const L=[];SIT.forEach(r=>{const q=+r[6]||0;if(q||all)L.push({opis:'Poz. '+r[0]+' '+r[1],em:r[2],cena:kPrice('Poz. '+r[0]+' '+r[1],p)||kPrice(r[1],p),q})});DOD.filter(r=>r[6]==='potrjeno').forEach(r=>{const q=+r[5]||0;if(q||all)L.push({opis:r[0]+' '+r[1],em:r[2],cena:kPrice(r[0]+' '+r[1],p)||kPrice(r[1],p),q})});if(!L.length){toast('V situaciji za '+curShort()+' še ni vpisanih količin. Izberi »vse postavke«.');return}S.kf.lines=L;S.kf.src='situacija';render();toast(L.length+' postavk prevzetih iz situacije za '+curShort()+'. Količine in cene lahko popraviš.')}
function kfSet(i,k,v){const L=S.kf.lines[i];L[k]=k==='opis'||k==='em'?v:num(v);render()}
function kfSave(){const p=PODI.find(x=>x.id===S.kf.pid);const L=S.kf.lines.filter(l=>l.q&&l.cena);if(!L.length){toast('Vpiši vsaj eno količino in ceno');return}const zn=r2(L.reduce((a,l)=>a+l.q*l.cena,0));KOOP.unshift({p:p.id,k:p.naziv,m:curShort(),sis:S.kf.sis||'Suhomontažna dela',lines:L.map(l=>({opis:l.opis,em:l.em,cena:l.cena,q:l.q})),opis:L.map(l=>`${l.opis} ${e(l.q)} ${l.em} × ${e(l.cena)}`).join(' · '),zn,rac:null});log('Obračun podizvajalcu, '+CO().name,p.naziv+' '+curShort()+', '+e(zn)+' €');S.kf=null;render();toast('Obračun za '+p.naziv+' pripravljen ('+e(zn)+' €). Izvoziš ga z gumbom Excel ali PDF v tabeli.')}
const SIS=['Suhomontažna dela','Slikopleskarska dela','Zidarska dela','Rušitvena dela','Fasaderska dela','Keramičarska dela','Tlakarska dela','Elektro instalacije','Strojne instalacije','Mizarska dela','Kleparska in krovska dela','Drugo'];
