function kExpX(i){const k=KOOP[i],o=CO();const L=kLines(k);const rows=[['Montaža Škerjanec d.o.o. · Obračun del podizvajalcu'],['Podizvajalec',k.k],['Objekt',o.name],['Obdobje',mFull(k.m)],['Sistem',k.sis||'Suhomontažna dela'],[],['Zap.','Postavka','em','Količina','Cena €/em','Vrednost €'],...L.map((l,j)=>[j+1,l.opis,l.em,+l.q||0,+l.cena||0,r2((+l.q||0)*(+l.cena||0))]),[],['','Skupaj brez DDV','','','',r2(k.zn)]];xlsx(kName(k)+'.xlsx',[['Obračun',rows,[6,60,6,10,10,12]]])}
async function kDel(i){const k=KOOP[i];if(!k)return;if(!await uiConfirm('Izbrišem obračun '+k.k+' · '+mFull(k.m)+' ('+e(k.zn)+')?'))return;KOOP.splice(i,1);log('Obračun podizvajalcu '+k.k,'izbrisan ('+mFull(k.m)+')');save();render();toast('Obračun izbrisan')}
function kExpC(i){const k=KOOP[i],o=CO();if(!k)return;const r=o.ddv==='76.a'?0:o.ddv==='9,5 %'?9.5:22;const z=+k.zn||0;csv(kName(k)+'.csv',[['Vrsta','Številka','Datum','Partner','Davčna št.','Objekt','Sklic','Osnova','DDV %','DDV','76.a','Za plačilo'],['prejeti račun / obračun podizvajalca','','',k.k,'',o.name,mFull(k.m)+' · '+(k.sis||'Suhomontažna dela'),D2(z),String(r).replace('.',','),D2(z*r/100),o.ddv==='76.a'?'da':'ne',D2(z*(1+r/100))]])}
function kExpP(i){const k=KOOP[i],o=CO();const L=kLines(k);const tot=L.reduce((a,l)=>a+(+l.q||0)*(+l.cena||0),0)||k.zn;pdf(kName(k)+'.pdf',head('OBRAČUN DEL PODIZVAJALCU',`<b>Podizvajalec:</b> ${k.k}${(PODI.find(p=>p.id===k.p)||{}).kontakt?'<br><span style="color:#555">'+PODI.find(p=>p.id===k.p).kontakt+'</span>':''}<br><b>Objekt:</b> ${o.name}<br><b>Obdobje:</b> ${mFull(k.m)} · <b>Sistem:</b> ${k.sis||'Suhomontažna dela'}`)+tbl(['Zap.','Postavka','em','Količina','Cena €/em','Vrednost'],L.map((l,j)=>[j+1,l.opis,l.em,e(+l.q||0),e(+l.cena||0),e((+l.q||0)*(+l.cena||0))]),[0,0,0,1,1,1])+`<table style="width:50%;margin-left:50%;margin-top:12px;font-size:13px"><tr><td><b>Skupaj brez DDV</b></td><td style="text-align:right"><b>${e(tot)} €</b></td></tr></table><div style="margin-top:14px;font-size:11px">Na podlagi tega obračuna izstavite račun z navedbo objekta in obdobja.</div><div style="display:flex;justify-content:space-between;margin-top:30px;font-size:12px"><div>Pripravil:<br><b>Montaža ŠKERJANEC d.o.o.</b></div><div>Potrdil podizvajalec:<br><br>____________________</div></div>`)}
function koopSection(o){const f=S.kf;const fp=f&&PODI.find(x=>x.id===f.pid);
 return `<datalist id="sislist">${SIS.map(x=>`<option value="${x}">`).join('')}</datalist>${f?`<h2>Obračun · ${fp.naziv} · ${curShort()}</h2><div class="panel pad mb"><div class="flex mb" style="margin-bottom:8px"><span class="small muted">Sistem</span><input list="sislist" value="${(f.sis||'Suhomontažna dela').replace(/"/g,'&quot;')}" onchange="S.kf.sis=this.value" style="min-width:220px" aria-label="Sistem"></div><div class="tw"><table class="t"><thead><tr><th>Postavka</th><th>em</th><th class="n">Količina</th><th class="n">Cena</th><th class="n">Znesek</th></tr></thead><tbody>${f.lines.map((l,i)=>`<tr><td><input value="${String(l.opis).replace(/"/g,'&quot;')}" onchange="kfSet(${i},'opis',this.value)" style="width:100%" aria-label="Postavka"></td><td><input value="${l.em}" onchange="kfSet(${i},'em',this.value)" style="width:52px" aria-label="Enota"></td><td class="n"><input class="qin" value="${l.q?e(l.q):''}" onchange="kfSet(${i},'q',this.value)" aria-label="Količina"></td><td class="n"><input class="qin" value="${l.cena?e(l.cena):''}" onchange="kfSet(${i},'cena',this.value)" aria-label="Cena"></td><td class="n">${e(l.q*l.cena)}</td></tr>`).join('')}<tr class="sum"><td>Skupaj</td><td></td><td></td><td></td><td class="n">${e(f.lines.reduce((a,l)=>a+l.q*l.cena,0))}</td></tr></tbody></table></div><div class="flex mt"><button class="sm" onclick="S.kf.lines.push({opis:'',em:'m²',cena:0,q:0});render()">Dodaj vrstico</button><button class="sm" onclick="kfFromSit(false)">Prevzemi popis iz situacije</button><button class="sm" onclick="kfFromSit(true)">Prevzemi vse postavke popisa</button><button class="pri" onclick="kfSave()">Shrani obračun</button><button class="sm" onclick="S.kf=null;render()">Prekliči</button></div><div class="small muted" style="margin-top:6px">${f.src==='situacija'?'Postavke so prevzete iz popisa situacije za '+curShort()+'. Cene so iz zadnjega obračuna temu podizvajalcu na objektu, sicer iz cenika za kooperante.':'V situaciji za ta mesec še ni količin, vpiši postavke ali prevzemi vse postavke popisa.'} Vse je mogoče popraviti. »Prevzemi popis iz situacije« vzame postavke s količino ta mesec, »vse postavke popisa« tudi tiste brez količine.</div></div>`:''}
 <h2>Obračuni podizvajalcem na tem objektu</h2><div class="panel mb"><div class="tw"><table class="t"><thead><tr><th>Podizvajalec</th><th>Obdobje</th><th>Sistem</th><th class="n">Po obračunu</th><th></th></tr></thead><tbody>${KOOP.length?KOOP.map((k,i)=>`<tr><td>${k.k}</td><td>${mFull(k.m)}</td><td>${k.sis||'Suhomontažna dela'}</td><td class="n">${e(k.zn)}</td><td style="white-space:nowrap;text-align:right"><button class="sm" onclick="kExpX(${i})">Excel</button> <button class="sm" onclick="kExpP(${i})">PDF</button> <button class="sm" onclick="kExpC(${i})" title="CSV za računovodstvo (VASCO)">CSV</button> <button class="sm" onclick="kDel(${i})" title="Izbriši obračun">Izbriši</button></td></tr>`).join(''):'<tr><td colspan="5" class="muted">Še ni obračunov.</td></tr>'}<tr class="sum"><td>Skupaj</td><td></td><td></td><td class="n">${e(koopSum())}</td><td></td></tr></tbody></table></div></div>`}
function pPodi(o){const ta=(i,k,v,ph)=>`<textarea rows="1" placeholder="${ph}" onchange="podiSet(${i},'${k}',this.value)" oninput="this.style.height='auto';this.style.height=this.scrollHeight+'px'" style="width:100%;resize:none;overflow:hidden;font:inherit;border:1px solid var(--line2);border-radius:var(--r);padding:5px 7px;background:var(--panel);color:var(--ink);line-height:1.4" aria-label="${ph}">${String(v||'').replace(/</g,'&lt;')}</textarea>`;
 const koopRows=[];PODI.forEach(p=>p.cene.forEach(c=>koopRows.push([p.naziv,...c,'dogovorjena cena na objektu'])));Object.values(OBJ).filter(x=>x.full&&!o&&canSee(x)).forEach(xo=>{const d=dataOf(xo.id)||{};(d.KOOP||[]).forEach(k=>{const p=PODI.find(x=>x.plan===k.k);koopRows.push([p?p.naziv:k.k,'Obračun '+k.m,'kpl',k.zn,xo.name,k.rac==null?'obračun, čaka račun':'obračun, račun '+e(k.rac)+' €'])})});const here=r=>!o||o.name===r[4]||o.name.includes(r[4]);const rowsH=koopRows.filter(here);const onObj=p=>o&&(p.cene.some(c=>o.name.includes(c[3]))||podiObj(p).includes(o.name));
 return `<div class="between mb"><div></div><button class="pri" onclick="podiAdd()">Dodaj podizvajalca</button></div>
 <div class="grid3 mb">${PODI.map((p,i)=>[p,i]).sort((a,b)=>onObj(b[0])-onObj(a[0])).map(([p,i])=>{const ob=podiObj(p);return `<div class="panel pad small" style="${onObj(p)?'border-color:var(--blue)':''}"><div class="between" style="align-items:flex-start"><div><div style="font-weight:600;font-size:14px">${p.naziv}</div></div><button class="sm" onclick="podiDel(${i})" aria-label="Odstrani">✕</button></div>
 <div class="muted" style="margin:6px 0 2px">Kontakt</div>${ta(i,'kontakt',p.kontakt,'ime in priimek, telefon, e-pošta')}
 <div class="muted" style="margin:6px 0 2px">Sistemi, ki jih izvaja</div>${ta(i,'sistemi',p.sistemi,'npr. W112, stropi, mansarde')}
 <div class="flex" style="margin-top:8px">${o&&o.full?`<button class="sm" onclick="koopForm('${p.id}')">Pripravi obračun</button>`:''}<a class="small" style="color:var(--blue);cursor:pointer" onclick="S.kfil='${p.id}';render()">Vsi obračuni (${podiKoop(p).length})</a></div></div>`}).join('')}</div>${S.kfil?podiAll(PODI.find(x=>x.id===S.kfil)):''}${o&&o.full?koopSection(o):''}
 <div class="mt">${ponHead('kcen','<h2 style="margin:0">Cenik za kooperante</h2>')}</div>${pHid('kcen')?'':`<div class="panel"><table class="t"><thead><tr><th>Postavka</th><th>em</th><th class="n">€/em</th></tr></thead><tbody>${CEN_KOOP.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td class="n">${typeof r[2]==='number'?e(r[2]):r[2]}</td></tr>`).join('')}</tbody></table></div><div class="note mt">Iz Ceniki › Kooperanti${(()=>{const V=(CENX&&CENX.ver&&CENX.ver.kooperanti)||[];return V.length?', velja od '+fd(V[0].date):', velja od 1. 4. 2026'})()}. Samo delo, brez bandaže. Glede na velikost objekta ±10 %.</div>`}`}
async function renObj(id){const o=OBJ[id];const n=await uiPrompt('Novo ime objekta:',o.name);if(n===null)return;const v=n.trim();if(!v){toast('Ime ne sme biti prazno');return}if(v===o.name)return;const old=o.name;o.name=v;POVP.forEach(p=>{if(p.obj===id&&p.proj===old)p.proj=v});log('Objekt '+o.code,'preimenovan: '+old+' → '+v);save();render();toast('Objekt preimenovan')}
async function setDone(id,v){const o=OBJ[id];if(v&&!await uiConfirm('Označim objekt »'+o.name+'« kot končan? Pospravi se med končane objekte, podatki ostanejo.'))return;o.done=v?new Date().toISOString().slice(0,10):null;log('Objekt '+o.name,v?'označen kot končan':'vrnjen med aktivne');if(v){menuGo('objekti');toast('Objekt pospravljen med Končane objekte')}else{render();toast('Objekt je spet med aktivnimi')}}
const UROLES=['vodja projekta','računovodstvo','direktor','administrator','administrator, vodja projekta'];
function roleAccess(v){return /administrator/.test(v)?'vse':v==='direktor'?'vse, urejanje cenikov':v==='računovodstvo'?'vse razen poročil':'svoji objekti, svoja povpraševanja in ponudbe, plan ekip in ure'}
function addUser(){S.uEdit='new';render();setTimeout(()=>{const el=document.getElementById('ue_n');if(el)el.focus()},0)}
function uSave(){const k=S.uEdit;const n=document.getElementById('ue_n').value.trim(),m=document.getElementById('ue_m').value.trim().toLowerCase(),v=document.getElementById('ue_v').value;
 if(!n){toast('Vpiši ime uporabnika');return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(m)){toast('Uporabniško ime mora biti službeni e-naslov');return}
 if(USERS.some((r,i)=>i!==k&&r[1].toLowerCase()===m)){toast('Uporabniško ime '+m+' že obstaja');return}
 if(k==='new'){USERS.push([n,m,v,roleAccess(v),'ni povezan']);log('Uporabniki','dodan '+n+' ('+v+')');toast('Uporabnik dodan. Ob prvi prijavi nastavi svoje geslo.')}
 else{const r=USERS[k];if(/administrator/.test(r[2])&&!/administrator/.test(v)&&USERS.filter(x=>/administrator/.test(x[2])).length<2){toast('Ostati mora vsaj en administrator');return}const ch=[];if(r[0]!==n)ch.push('ime '+r[0]+' → '+n);if(r[1]!==m)ch.push('uporabniško ime '+r[1]+' → '+m);if(r[2]!==v)ch.push('vloga '+r[2]+' → '+v);r[0]=n;r[1]=m;r[2]=v;r[3]=roleAccess(v);if(ch.length)log('Uporabniki',n+': '+ch.join(', '));toast(ch.length?'Spremembe shranjene'+(ch.some(x=>x.startsWith('vloga'))?'. Nova vloga velja ob naslednji prijavi.':''):'Ni sprememb')}
 S.uEdit=null;save();render()}
async function uDel(i){const r=USERS[i];if(i===0||(window._user&&r[1]===String(window._user).toLowerCase())){toast('Samega sebe ne moreš izbrisati');return}if(/administrator/.test(r[2])&&USERS.filter(x=>/administrator/.test(x[2])).length<2){toast('Ostati mora vsaj en administrator');return}
 if(!await uiConfirm('Izbrišem uporabnika '+r[0]+' ('+r[1]+')?\n\nUporabnik se ne bo več mogel prijaviti. Objekti, ponudbe in vnosi, ki jih je naredil, ostanejo.'))return;USERS.splice(i,1);log('Uporabniki','izbrisan '+r[0]+' ('+r[1]+')');save();render();toast('Uporabnik '+r[0]+' izbrisan')}
function canSee(o){return !!o&&(S.role!=='nejc'||o.vodja===ME)}
function canDel(vodja){return S.role==='admin'||S.role==='direktor'||vodja===ME}
async function delObj(id){const o=OBJ[id];if(!o)return;if(!canDel(o.vodja)){toast('Objekt lahko izbriše samo njegov vodja ali administrator');return}const d=dataOf(id)||{PREV:[]};if(id==='sencur'&&CUR==='sencur'?PREV.length:(d.PREV||[]).length){toast('Objekt ima izdane situacije oz. račune, zato ga ni mogoče izbrisati. Popravek gre z dobropisom.');return}
 if(!await uiConfirm('Izbrišem objekt »'+o.name+'«? Premakne se v koš, administrator ga lahko obnovi.'))return;if(CUR===id){const alt=Object.keys(OBJ).find(k=>k!==id&&OBJ[k].full);if(alt)useObj(alt)}TRASH.unshift({kind:'objekt',when:new Date().toISOString(),who:MSD.who(),obj:JSON.parse(JSON.stringify(OBJ[id]))});delete OBJ[id];
 const pv=POVP.find(p=>p.num===o.pon&&p.st==='potrjeno');if(pv)pv.st='nepotrjeno';log('Objekt '+o.name,'izbrisan (v košu)');go('objekti');toast('Objekt izbrisan in premaknjen v koš'+(pv?'. Ponudba '+pv.num+' je spet nepotrjena.':''))}
function dodArr(id){if(id===CUR)return {DOD,MONTHS};const o=OBJ[id];return o&&o.d?o.d:null}
function dodPon(id){const o=OBJ[id];DRAFT=draftFrom(null);DRAFT.nar=[o.client||''];DRAFT.proj=o.name+' – dodatna dela';DRAFT.ddv=o.ddv||'76.a';DRAFT.obj=id;go('nova')}
const DCOL=['#2E9C96','#7E5BC4','#F2A93B','#D9453B','#4CAF73'];
function bar(pct,col,label){const w=Math.max(0,Math.min(100,pct||0));return `<div style="height:6px;background:var(--line);border-radius:3px;margin-top:10px"><div style="height:6px;border-radius:3px;background:${col};width:${w}%"></div></div><div class="small muted" style="margin-top:4px">${label}</div>`}
function progBars(o,t){const rate=o.rate||0;let h=o.pogodba?bar(t.main*(1-rate)/o.pogodba*100,'var(--blue)',`${Math.round(t.main*(1-rate)/o.pogodba*100)} % pogodbenih del`):'';
 const P=POVP.filter(p=>p.obj===o.id&&p.st!=='zavrnjeno');const ex={};DOD.forEach(r=>{const k=r[9]||'';const q=r[4].reduce((a,b)=>a+b,0)+(+r[5]||0);ex[k]=(ex[k]||0)+q*r[3]*(1-(+r[10]||0))});
 P.forEach((p,i)=>{const v=ex[p.num]||0;const tot=+p.total||0;const pc=tot?v/tot*100:0;const col=DCOL[i%DCOL.length];h+=bar(p.st==='potrjeno'?pc:0,col,`<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${col};margin-right:5px"></span>${p.st==='potrjeno'?Math.round(pc):0} % po ponudbi ${p.num}`)});

 return h}
function objPct(o){if(!o.pogodba)return null;if(o.id===CUR||(o.d&&o.d.SIT)){const t=sitTotals(o.id);return t.main*(1-(o.rate||0))/o.pogodba*100}return o.obr!=null?o.obr/o.pogodba*100:null}
function dodFin(o){const L=POVP.filter(p=>p.obj===o.id);if(!L.length)return '';const ok=L.filter(p=>p.st==='potrjeno').reduce((a,p)=>a+(+p.total||0),0),nok=L.filter(p=>p.st==='nepotrjeno').reduce((a,p)=>a+(+p.total||0),0);return `<span>Dodatne ponudbe, potrjene</span><span style="text-align:right">${e(ok)}</span>${nok?`<span>Dodatne ponudbe, nepotrjene</span><span style="text-align:right" class="warnline">${e(nok)}</span>`:''}`}
function dodPanel(o){const L=POVP.map((p,i)=>[p,i]).filter(([p])=>p.obj===o.id);
 const stb=st=>st==='potrjeno'?'<span class="badge b-ok">potrjena</span>':st==='zavrnjeno'?'<span class="badge b-bad">zavrnjena</span>':st==='v pripravi'?'<span class="badge b-gray">v pripravi</span>':'<span class="badge b-warn">nepotrjena</span>';
 const ok=L.filter(([p])=>p.st==='potrjeno').reduce((a,[p])=>a+(+p.total||0),0);
 const pot=L.filter(([p])=>p.st==='potrjeno');const sec=pot.map(([p])=>{const it=p.items&&p.items.length?p.items:[{poz:'1',opis:'Dela po dodatni ponudbi '+p.num+' (glej popis)',em:'kpl',q:1,c:r2((+p.total||0)/((1-(p.pop||0)/100)||1))}];const rows=it.map(x=>[x.poz,x.opis,x.em,+x.q||0,+x.c||0]);const sum=rows.reduce((a,r)=>a+r[3]*r[4],0);return `<div class="mt">`+ponHead(p.num,`<span style="font-size:16px;font-weight:600">${p.num}</span><span class="badge b-ok">potrjena · zaklenjena</span>`)+(pHid(p.num)?'':ponTab(rows,sum,(p.pop||0)/100,'')+dolPanel(p))+`</div>`}).join('');
 return `<div class="between mt mb" style="align-items:center"><h2 style="margin:0">Dodatne ponudbe</h2><button class="pri" onclick="dodPon('${o.id}')">Dodaj ponudbo</button></div><div class="panel"><div class="tw"><table class="t"><thead><tr><th>Številka</th><th>Vsebina</th><th>Stanje</th><th>Poslano</th><th>Podlaga za potrditev</th><th class="n">Vrednost</th><th></th></tr></thead><tbody>${L.length?L.map(([p,i])=>`<tr><td>${p.st==='potrjeno'?`<a style="cursor:pointer;color:var(--blue)" onclick="pTog('${p.num}')">${p.num}</a>`:p.num}</td><td>${p.proj}</td><td>${stb(p.st)}</td><td>${p.sent?fd(p.sent):'—'}</td><td class="small muted">${p.podlaga||''}</td><td class="n">${p.total?e(p.total):'—'}</td><td style="white-space:nowrap;text-align:right">${p.st==='v pripravi'||p.st==='nepotrjeno'?`<button class="sm" onclick="novaPonudba(${i})">Uredi</button> `:''}${p.st==='v pripravi'?`<button class="sm" onclick="pvSent(${i})" title="Ponudbo si poslal naročniku po e-pošti">Poslano</button> `:p.st==='nepotrjeno'?`<button class="sm" onclick="pvSet(${i},'potrjeno')">Potrjeno</button> <button class="sm" onclick="pvSet(${i},'zavrnjeno')">Zavrnjeno</button> `:''}${canDel(p.vodja)?`<button class="sm" onclick="delPon(${i})">Izbriši</button>`:''}</td></tr>`).join('')+`<tr class="sum"><td></td><td>Potrjene dodatne ponudbe skupaj</td><td></td><td></td><td></td><td class="n">${e(ok)}</td><td></td></tr>`:'<tr><td colspan="7" class="muted">Ni dodatnih ponudb.</td></tr>'}</tbody></table></div></div>`+sec}
async function pvDodOk(i){const p=POVP[i];const o=OBJ[p.obj];const d=dodArr(p.obj);if(!o||!d){toast('Objekt te ponudbe ne obstaja več');return}
 const pod=await uiPrompt('Podlaga za potrditev (aneks, naročilnica, e-pošta, vpis v gradbeni dnevnik):');if(pod===null)return;if(!pod.trim()){toast('Brez podlage za potrditev dodatna dela ne gredo v situacijo');return}
 const rate=(p.pop||0)/100;const items=p.items&&p.items.length?p.items:[{poz:'1',opis:'Dela po dodatni ponudbi '+p.num+' (glej popis)',em:'kpl',q:1,c:r2((+p.total||0)/((1-rate)||1))}];
 let n=d.DOD.reduce((m,r)=>Math.max(m,+((String(r[0]).match(/\d+/)||[0])[0])),0);
 items.forEach(x=>d.DOD.push(['D'+(++n),x.opis,x.em,r2(+x.c||0),(d.MONTHS||[]).map(()=>0),0,'potrjeno',p.num+' · '+pod.trim(),false,p.num,rate]));
 const td=new Date().toISOString().slice(0,10);p.st='potrjeno';p.podlaga=pod.trim();p.conf=td;if(o.ev)o.ev.push([fd(td),'Dodatna ponudba '+p.num+' potrjena ('+p.podlaga+')']);
 log('Dodatna ponudba '+p.num,'potrjena · '+p.podlaga+' · '+items.length+' postavk v situacijo');save();render();toast('Dodatna ponudba potrjena, '+items.length+' postavk je v situaciji pod Dodatna dela')}
