function ureCost(id){pLegInit();const o=OBJ[id];if(!o)return {h:0,hf:0,by:{}};const nm=o.name.split(',')[0];const cs=new Set([o.code,...PLEG.filter(x=>x.name===nm).map(x=>x.code)].filter(Boolean));const td=cToday();let h=0,hf=0,hr=0;const by={};
 PLAN.own.forEach((r,ri)=>{const days=new Set(Object.keys(r.d||{}));for(let k=0;k<7;k++)days.add(pAdd(PBASE,k));days.forEach(iso=>{const p=cHrs(pGet(r,iso));let x=0,xr=0;cs.forEach(c=>{x+=p.out[c]||0;xr+=p.out['R-'+c]||0});x+=xr;if(!x)return;if(iso<=td){h+=x;hr+=xr;const n=uNm(r);by[n]=(by[n]||0)+x}else hf+=x})});return {h,hf,hr,by}}
