function num(v){return parseFloat(String(v).replace(/\./g,'').replace(',','.'))||0}
function izmSet(i,k,v){if(IZM[i].t){toast('Izmera je že prenesena v situacijo');render();return}IZM[i][k]=num(v);render()}
async function izmHand(i){if(IZM[i].t){toast('Izmera je že prenesena v situacijo. Popravek gre v naslednjo situacijo.');return}const r=IZM[i];const cur=r.hand!=null?r.hand:(r.l*r.h);const v=await uiPrompt('Ročno vpiši neto m² za '+r.o+' (prazno za izračun):',e(cur));if(v===null)return;if(v.trim()===''){delete r.hand}else{r.hand=num(v)}render();toast(v.trim()===''?'Vrnjeno na izračun':'Zapisano kot ročni popravek · Nejc, zdaj')}
function izmNet(r){if(r.hand!=null)return r.hand;let od=0;if(r.od){od=Math.max(0,r.od[0]*r.od[1]-2.5)}return r.l*r.h-od}
function prenesi(){const open=IZM.filter(r=>r.m!=='apr'&&!r.t);if(!open.length){toast('Ni novih izmer za prenos');return}if(SITST.st!=='v pripravi'){toast('Situacija je v uskladitvi, prenos ni mogoč');return}const q=open.reduce((a,r)=>a+izmNet(r),0);const by={};open.forEach(r=>{const p=r.p||0;by[p]=(by[p]||0)+izmNet(r)});Object.entries(by).forEach(([p,x])=>{SIT[p][6]=Math.round(((+SIT[p][6]||0)+x)*100)/100});open.forEach(r=>{r.t=true;r.m=curShort()});log('Situacija '+SITST.n+', '+CO().name,'+'+e(q)+' iz izmer');render();toast(e(q)+' preneseno v '+SITST.n+'. situacijo')}
function addIzm(){IZM.push({o:'A'+(IZM.length+1),p:S.izp||0,l:3.00,h:2.60,od:null,src:'objekt',k:'Kooperant Miha',m:curShort()});render();toast('Dodana nova izmera, popravi dolžino in višino')}
function potrdiDod(i){log('Dodatna dela, '+CO().name,DOD[i][0]+' potrjeno');DOD[i][6]='potrjeno';DOD[i][7]='Nejc vpisal potrditev, e-pošta naročnika danes';render();toast('Potrditev zapisana z datumom in povezavo na e-pošto')}
function tSituacije(o){
 const t=sitTotals();
 const mc=MONTHS.length;
 const row=(r,isD,ix)=>{const q=isD?r[4]:r[5],price=isD?r[3]:r[4],pog=isD?null:r[3],may=isD?r[5]:r[6];const sum=q.reduce((a,b)=>a+b,0)+(+may||0);const over=pog!=null&&sum>pog;return `<tr><td>${r[0]}</td><td>${r[1]}${isD&&r[6]==='čaka'?` <span class="badge b-warn">čaka potrditev</span> <button class="sm" onclick="potrdiDod(${ix})">Vpiši potrditev</button>`:''}</td><td>${r[2]}</td><td class="n">${pog!=null?e(pog):'—'}</td><td class="n">${e(price)}</td>${q.map(x=>`<td class="n muted">${x?e(x):''}</td>`).join('')}<td class="n"><input class="qin" value="${may?e(may):''}" onchange="setMay(${isD?1:0},${ix},this.value)"  aria-label="${curM()} ${r[0]}" ${isD&&r[6]==='čaka'?'title="Najprej vpiši potrditev"':''}></td><td class="n ${over?'warnline':''}">${e(sum)}</td><td class="n">${pog?Math.round(sum/pog*100)+' %':''}</td><td class="n">${e(sum*price)}</td></tr>`};
 const locked=SITST.st!=='v pripravi';
 const om=SITST.m||openM(SITST,MONTHS);const yrs=[];const y0=+om.slice(0,4);for(let y=y0-3;y<=y0+3;y++)yrs.push(y);
 return `<div class="pills" style="align-items:center">${MONTHS.map((x,i)=>`<a onclick="toast('Zaključena situacija, PDF je v Dokumenti → ${fL('09')}')">Situacija ${i+1} <span style="opacity:.65">· ${mLab(x)}</span><span role="button" aria-label="Izbriši situacijo ${i+1}" title="Izbriši situacijo" onclick="event.stopPropagation();sitDel(${i})" style="margin-left:6px;opacity:.55;cursor:pointer;padding:0 2px">✕</span></a>`).join('')}<span class="flex" style="gap:4px;padding:2px 6px;border-radius:14px;background:var(--ink);color:var(--panel)"><b style="font-weight:500;padding-left:4px">Situacija ${SITST.n} ·</b><select aria-label="Mesec situacije" onchange="setSitM(this.value,null)" style="padding:2px 4px;color:var(--ink);background:var(--panel)">${MN.map((n,mi)=>`<option value="${mi+1}" ${+om.slice(5)===mi+1?'selected':''}>${n}</option>`).join('')}</select><select aria-label="Leto situacije" onchange="setSitM(null,this.value)" style="padding:2px 4px;color:var(--ink);background:var(--panel)">${yrs.map(y=>`<option ${y===y0?'selected':''}>${y}</option>`).join('')}</select></span><button class="sm" onclick="sitPlus()" title="Zaključi to situacijo in dodaj naslednjo" aria-label="Dodaj situacijo">+</button></div>
 <div class="panel"><div class="tw"><table class="t" style="min-width:980px"><thead><tr><th>Poz</th><th>Postavka</th><th>em</th><th class="n">Pogodba</th><th class="n">€/em</th>${MONTHS.map(m=>`<th class="n">${mLab(m)}</th>`).join('')}<th class="n" style="color:var(--blue)">${curM()}</th><th class="n">Skupaj</th><th class="n">%</th><th class="n">Vrednost</th></tr></thead><tbody>
 <tr class="grp"><td colspan="${mc+9}">Dela po pogodbi in več dela · ponudba ${mainPon()}</td></tr>${SIT.map((r,ix)=>row(r,false,ix)).join('')}
 ${(()=>{const g=[];DOD.forEach((r,ix)=>{const k=r[9]||'';let x=g.find(y=>y.k===k);if(!x)g.push(x={k,r:[]});x.r.push(row(r,true,ix))});if(!g.length)g.push({k:'',r:[]});g.sort((a,b)=>(a.k?1:0)-(b.k?1:0));return g.map(x=>`<tr class="grp"><td colspan="${mc+9}">Dodatna dela${x.k?' · ponudba '+x.k:''}</td></tr>`+x.r.join('')).join('')})()}
 </tbody></table></div></div>
 <div class="grid2 mt"><div><div class="note">Vpiši količine za ${curShort()} v modri stolpec ali jih prenesi iz izmer. Kumulativa, odstotki, popust samo na pogodbena dela in odbitki prejšnjih situacij se izračunajo sami. Postavki 2a in 16 že presegata pogodbo in sta označeni.</div>${t.mainMay+t.dodMay>0?`<div class="note mt">Ta mesec: pogodbena ${e(t.mainMay)} €, dodatna ${e(t.dodMay)} €</div>`:''}</div>
 <div class="panel pad"><div class="kv">
 <span>Pogodbena dela in več dela · ponudba ${mainPon()}</span><span style="text-align:right">${e(t.main)}</span>
 <span>Popust ${pct()} % na pogodbena dela · ponudba ${mainPon()}</span><span style="text-align:right">−${e(t.pop)}</span>
 ${dodSplit().map(x=>`<span>${x[0]}</span><span style="text-align:right">${eS(x[1])}</span>`).join('')}
 <span style="color:var(--ink);font-weight:500">Skupaj izvedeno</span><span style="text-align:right;font-weight:500">${e(t.tot)}</span>
 ${PREV.map(p=>`<span>${p[0]}</span><span style="text-align:right">−${e(p[1])}</span>`).join('')}
 <span style="color:var(--ink);font-weight:600;font-size:15px">Za plačilo brez DDV</span><span style="text-align:right;font-weight:600;font-size:15px">${e(t.pay)} €</span>
 ${ddvUi(t.pay,CO().ddv)}${t.zp?`<span>Zadržek ${String(t.zp).replace('.',',')} % (do konca garancije)</span><span style="text-align:right">−${e(t.ret)}</span><span style="color:var(--ink);font-weight:600">Za izplačilo</span><span style="text-align:right;font-weight:600">${e(t.net)} €</span><span>Skupaj zadržano z to situacijo</span><span style="text-align:right">${e(t.retAll)}</span>`:''}</div><div class="small muted mt" style="margin-top:6px">${CO().ddv==='76.a'?'Obrnjena davčna obveznost po 76.a členu ZDDV-1: DDV ni obračunan, znesek je izkazan za naročnika':'DDV '+CO().ddv}</div>
 <div class="flex mt"><button onclick="expSitX()">Izvozi Excel</button><button onclick="expSitP()">Ustvari PDF</button></div><div class="small muted" style="margin-top:6px">Mesec situacije izbereš zgoraj. Z gumbom + situacijo zaključiš (PDF se shrani v Dokumenti → ${fL('09')}) in dodaš naslednjo; prejšnje ostanejo vidne kot stolpci.</div></div></div></div>`;
}
async function autoSitDoc(stage){try{const o=CO();const n=SITST.n;const name=n+'. začasna situacija '+fnm(o)+'.pdf';const ab=await expSitP(true);if(!ab)return;const old=FILES.filter(x=>x.obj===o.id&&x.auto===o.id+'-'+n);old.forEach(x=>fDel(x.id));FILES=FILES.filter(x=>!(x.obj===o.id&&x.auto===o.id+'-'+n));const id='f'+Date.now().toString(36);await fPut(id,ab);FILES.push({id,obj:o.id,folder:'09',name,size:ab.byteLength,when:new Date().toISOString(),who:'samodejno',auto:o.id+'-'+n});render()}catch(x){}}
function setSitM(m,y){const cur=SITST.m||openM(SITST,MONTHS);const nm=(y||cur.slice(0,4))+'-'+String(m||+cur.slice(5)).padStart(2,'0');const last=MONTHS.length?mIso(MONTHS[MONTHS.length-1]):null;if(last&&nm<=last){toast('Mesec mora biti za zadnjo zaključeno situacijo ('+mLab(last)+')');render();return}SITST.m=nm;log('Situacija '+SITST.n+', '+CO().name,'mesec '+mLab(nm));render()}
function sitPlus(){sitClose()}
async function sitDel(i){const m=MONTHS[i];if(m==null)return;const pv=PREV[i]||['',0];const last=i===MONTHS.length-1;
 if(!await uiConfirm('Izbrišem '+(i+1)+'. situacijo · '+mLab(m)+' ('+e(pv[1]||0)+' €)?\n\nIzbrišejo se njene količine v kumulativi'+(last?'':', naslednje situacije se preštevilčijo')+'.'+(PAID[i]?'\nPozor: situacija je označena kot plačana.':'')+'\nPDF v Dokumenti → 09 ostane, izbrišeš ga ročno.'))return;
 MONTHS.splice(i,1);PREV.splice(i,1);PAID.splice(i,1);SIT.forEach(r=>r[5].splice(i,1));DOD.forEach(r=>r[4].splice(i,1));
 PREV.forEach((p,k)=>{if(/^\d+\./.test(p[0]))p[0]=p[0].replace(/^\d+\./,(k+1)+'.')});
 SITST.n=Math.max(1,SITST.n-1);const o=CO();o.sit=MONTHS.length?MONTHS.length+'. situacija · '+mLab(MONTHS[MONTHS.length-1]):'1. situacija v pripravi';o.obr=sitTotals().tot;
 log('Situacija, '+o.name,(i+1)+'. situacija · '+mLab(m)+' izbrisana');save();render();toast((i+1)+'. situacija izbrisana')}
async function sitClose(){const t=sitTotals();if(t.pay<=0){toast('Vpiši vsaj eno količino za '+curShort());return}if(!await uiConfirm('Zaključim '+SITST.n+'. situacijo za '+curShort()+' ('+e(t.pay)+' €) in dodam '+(SITST.n+1)+'. situacijo za '+mLab(mNext(SITST.m||openM(SITST,MONTHS)))+'? Prejšnje situacije ostanejo vidne.'))return;SITST.st='za račun';const r=S.role;S.role='admin';sitStep();S.role=r;render()}
function sitStep(){const t=sitTotals();if(SITST.st==='v pripravi'){if(t.pay<=0){toast('Vpiši vsaj eno količino za '+curShort());return}SITST.st='v uskladitvi';log('Situacija '+SITST.n+', '+CO().name,'poslana v uskladitev');autoSitDoc('uskladitev');toast('Situacija poslana naročniku v uskladitev')}else if(SITST.st==='v uskladitvi'){SITST.st='za račun';log('Situacija '+SITST.n+', '+CO().name,'usklajena');toast('Usklajeno. Računovodstvo vidi situacijo za izdajo računa.')}else{if(S.role!=='racun'&&S.role!=='admin'){toast('Račun izda računovodstvo. Zamenjaj vlogo zgoraj.');return}autoSitDoc('izdana');const pay=Math.round(t.pay*100)/100;const ml=curShort();MONTHS.push(SITST.m||openM(SITST,MONTHS));SIT.forEach(r=>{r[5].push(+r[6]||0);r[6]=0});DOD.forEach(r=>{r[4].push(+r[5]||0);r[5]=0});PREV.push([SITST.n+'. začasna situacija · '+ml,pay,Math.round(t.ret*100)/100]);PAID.push(false);log('Situacija, '+CO().name,SITST.n+'. situacija zaključena, '+e(pay)+' €');toast(SITST.n+'. situacija zaključena, PDF shranjen v '+fL('09'));SITST={n:SITST.n+1,st:'v pripravi',m:mNext(MONTHS[MONTHS.length-1]&&mIso(MONTHS[MONTHS.length-1])||nowIso())};CO().sit=(SITST.n-1)+'. situacija · '+mLab(MONTHS[MONTHS.length-1]);CO().obr=sitTotals().tot}render()}
function setMay(isD,poz,v){if(SITST.st!=='v pripravi'){toast('Situacija je v uskladitvi. Vrni jo v pripravo za spremembe.');render();return}const arr=isD?DOD:SIT;const r=arr[poz];if(isD&&r[6]==='čaka'&&num(v)>0){toast('Dodatno delo še ni potrjeno. Najprej vpiši potrditev.');render();return}r[isD?5:6]=num(v);render()}
function rzSet(i,k,v){if(!RAZNO[i])RAZNO[i]={kat:'',vir:'',zn:0};RAZNO[i][k]=k==='zn'?num(v):v;log('Stroški, '+CO().name,(RAZNO[i].kat||'Razno')+': '+k+' '+v);render()}
function cIn(k,v){const o=CO();const h=o.cOv&&o.cOv[k]!=null;return `${h?'<span class="badge b-hand" title="ročno popravljeno">ročno</span>':''}<input class="qin" style="width:100px" value="${e(v)}" onchange="cSet('${k}',this.value)" aria-label="Znesek">${h?` <a class="small" style="color:var(--blue);cursor:pointer" onclick="cSet('${k}',null)">ponastavi</a>`:''}`}
