function poslji(){const bad=POP.filter(p=>!p.ok||!p.q||!p.cena);if(bad.length){toast('Najprej potrdi vse vrstice in vpiši količine ('+bad.length+' manjka)');return}const tot=POP.reduce((a,p)=>a+p.q*p.cena,0);const r=PON.find(x=>x[0]==='0512-1/2026');r[3]='poslana';r[4]='b-gray';r[5]=Math.round(tot*100)/100;const pv0=POVP.find(p=>p.num==='0512-1/2026');if(pv0){pv0.st='nepotrjeno';pv0.sent=new Date().toISOString().slice(0,10);pv0.total=r2(tot)}log('Ponudba 0512-1/2026','poslana SGP Graditelj, '+e(tot)+' €');go('povp');toast('0512-1 poslana SGP Graditelj. Povpraševanje je posodobljeno.')}
