function pSituacije(){
 const L=[...Object.values(OBJ).filter(o=>o.full&&!o.done).map(o=>{const d=dataOf(o.id)||{SITST:{n:1,st:'v pripravi'},MONTHS:[]};const cm=mLab(openM(d.SITST,d.MONTHS));return [o.id,d.SITST.n+'. '+String(cm).split(' ')[0],d.SITST.st,d.SITST.st==='za račun'?'b-ok':'b-blue']}),['westlink','13. april','izdana, čaka plačilo','b-gray'],['kusar','7. junij','usklajena, za račun','b-ok'],['teograd','3. maj','izdana','b-gray']].filter(x=>canSee(OBJ[x[0]])).filter((x,i,a)=>!(i>0&&x[0]==='sencur'&&x[1].startsWith(String(OBJ.sencur&&0))));
 return `<div class="between mb"><div><h1>Situacije in računi</h1><div class="sub">Kaj je v pripravi, kaj čaka uskladitev in kaj je pripravljeno za račun</div></div><button onclick="expVasco()">Izvoz za računovodstvo (VASCO, CSV)</button></div>
 <div class="panel"><table class="t"><thead><tr><th>Objekt</th><th>Situacija</th><th>Stanje</th><th>Vodja</th></tr></thead><tbody>${L.map(r=>`<tr class="click" onclick="openObj('${r[0]}');S.tab='situacije';render()"><td>${OBJ[r[0]].name}</td><td>${r[1]}</td><td><span class="badge ${r[3]}">${r[2]}</span></td><td>${OBJ[r[0]].vodja}</td></tr>`).join('')}</tbody></table></div>`;
}
const PBASE='2026-10-12';const DN=['ned','pon','tor','sre','čet','pet','sob'];const MNS=['januar','februar','marec','april','maj','junij','julij','avgust','september','oktober','november','december'];
const pD=iso=>new Date(iso+'T00:00:00Z');const pIso=d=>d.toISOString().slice(0,10);const pAdd=(iso,n)=>{const d=pD(iso);d.setUTCDate(d.getUTCDate()+n);return pIso(d)};
const pMon=iso=>{const d=pD(iso);const k=(d.getUTCDay()+6)%7;return pAdd(iso,-k)};
function pGet(r,iso){if(r.d&&r.d[iso]!=null)return r.d[iso];const k=Math.round((pD(iso)-pD(PBASE))/864e5);return k>=0&&k<7?(r.c[k]||''):''}
function pDays(){if(S.pv==='m'){const m=S.pm||PBASE.slice(0,7);const y=+m.slice(0,4),mo=+m.slice(5,7);const n=new Date(Date.UTC(y,mo,0)).getUTCDate();return Array.from({length:n},(_,i)=>m+'-'+String(i+1).padStart(2,'0'))}const w=S.pw||PBASE;return Array.from({length:7},(_,i)=>pAdd(w,i))}
function pLabel(){if(S.pv==='y')return 'leto '+pYear();const D=pDays();if(S.pv==='m'){const d=pD(D[0]);return MNS[d.getUTCMonth()]+' '+d.getUTCFullYear()}const a=pD(D[0]),b=pD(D[6]);return a.getUTCDate()+'.'+(a.getUTCMonth()!==b.getUTCMonth()?' '+MNS[a.getUTCMonth()]:'')+' – '+b.getUTCDate()+'. '+MNS[b.getUTCMonth()]+' '+b.getUTCFullYear()}
function pNav(k){if(S.pv==='y'){S.py=pYear()+k;render();return}if(S.pv==='m'){const m=S.pm||PBASE.slice(0,7);const d=new Date(Date.UTC(+m.slice(0,4),+m.slice(5,7)-1+k,1));S.pm=pIso(d).slice(0,7)}else S.pw=pAdd(S.pw||PBASE,7*k);render()}
function pView(v){const cur=S.pv==='m'?(S.pm||PBASE.slice(0,7))+'-01':S.pv==='y'?pYear()+'-01-01':(S.pw||PBASE);if(v==='y'){S.py=+cur.slice(0,4);if(S.pv!=='y')S.pyFrom=cur;S.pv='y';render();return}if(S.pv==='y'){const base=S.pyFrom&&+S.pyFrom.slice(0,4)===pYear()?S.pyFrom:pYear()+'-01-01';S.pw=pMon(base);S.pm=base.slice(0,7)}if(v==='m'&&S.pv!=='y')S.pm=(S.pw||PBASE).slice(0,7);else if(v==='m')S.pm=S.pm||PBASE.slice(0,7);else S.pw=pMon((S.pm||PBASE.slice(0,7))===(S.pw||PBASE).slice(0,7)?(S.pw||PBASE):(S.pm||PBASE.slice(0,7))+'-01');S.pv=v;render()}
function pYear(){return S.py||+PBASE.slice(0,4)}
function pWeeks(){const y=pYear();let w=pMon(y+'-01-01');const out=[];while(pD(w).getUTCFullYear()<=y){if(pD(pAdd(w,6)).getUTCFullYear()>=y)out.push(w);w=pAdd(w,7)}return out}
function pWk(iso){const d=pD(pAdd(iso,3));const y0=new Date(Date.UTC(d.getUTCFullYear(),0,1));return Math.ceil(((d-y0)/864e5+1)/7)}
function pWeekVal(r,w){const cnt={};let ods=0;for(let i=0;i<7;i++){const v=pGet(r,pAdd(w,i));if(v==='ODS'||v==='DOP'||v==='BOL'){ods++;continue}[...new Set(cCodes(v).map(baseC).filter(Boolean))].forEach(c=>cnt[c]=(cnt[c]||0)+1)}const k=Object.keys(cnt).sort((a,b)=>cnt[b]-cnt[a]);return k.length?k.join('/'):(ods?'ODS':'')}
