function pViewBtns(){const v=S.pv||'w';return `<div class="flex" style="gap:4px">${[['w','Teden'],['m','Mesec'],['y','Leto']].map(x=>`<button class="sm ${v===x[0]?'pri':''}" onclick="pView('${x[0]}')">${x[1]}</button>`).join('')}</div>`}
