async function pDel(g,ri){const r=PLAN[g][ri];const n=r.n||'monter '+(ri+1);const t=new Date().toISOString().slice(0,10);if(!await uiConfirm('Monter »'+n+'« ne dela več od '+fd(t)+'?\n\nV preteklih tednih ostane viden z vsem planom, v prihodnjih tednih in mesecih ga ne bo več. Njegov plan od '+fd(t)+' naprej se izbriše.'))return;r.end=t;r.d=r.d||{};Object.keys(r.d).forEach(k=>{if(k>=t)delete r.d[k]});for(let k=0;k<7;k++){if(pAdd(PBASE,k)>=t)r.c[k]=''}const act=PLAN[g].filter(x=>!x.end).length;if(act<15)PLAN[g].push({n:'',c:['','','','','','',''],d:{}});log('Plan ekip','monter '+n+' ne dela več od '+fd(t));save();render();toast('Monter »'+n+'« ne dela več od '+fd(t))}
