function planMig(){try{if(PLAN.v2)return;const o=PLAN.own||[];const cp=r=>({c:(r&&r.c||[]).slice(),d:Object.assign({},r&&r.d||{})});let rows=[];if(o.length===2&&/Marko/.test(o[0].n)&&/Jure/.test(o[1].n))rows=[{n:'Marko',...cp(o[0])},{n:'Luka',...cp(o[0])},{n:'Jure',...cp(o[1])},{n:'Tilen',...cp(o[1])}];else rows=o.map(r=>({n:String(r.n||'').replace(/^Ekipa\s+/,'').split(' · ')[0],...cp(r)}));while(rows.length<15)rows.push({n:'',c:['','','','','','',''],d:{}});PLAN.own=rows.slice(0,Math.max(15,rows.length));PLAN.koop=[];PLAN.v2=true}catch(x){}}
