function pLegInit(){if(PLEG&&PLEG.length)return;const H={c1:'#E3EDF8',c2:'#E3F2E8',c3:'#FCF0D9',c4:'#EDE7F8',c5:'#E6F1F1'};PLEG=Object.entries(CODES).filter(([k])=>Object.values(OBJ).some(o=>o.code===k)).map(([k,c])=>({code:k,name:Object.values(OBJ).find(o=>o.code===k).name.split(',')[0],color:H[c]||'#E3EDF8'}))}
function pFg(hex){const h=hex.replace('#','');const r=parseInt(h.slice(0,2),16),g=parseInt(h.slice(2,4),16),b=parseInt(h.slice(4,6),16);return (0.299*r+0.587*g+0.114*b)>150?'#1F2A36':'#FFFFFF'}
