function pLegend(){pLegInit();return PLEG.map((x,i)=>`<span style="position:relative;display:inline-block"><span class="badge" title="Klikni za izbiro barve" onclick="S.plPick=S.plPick===${i}?null:${i};render()" style="background:${x.color};color:${pFg(x.color)};display:inline-flex;align-items:center;gap:4px;cursor:pointer">${x.code} ${x.name}<a onclick="event.stopPropagation();pLegDel(${i})" title="Odstrani iz legende" style="cursor:pointer;opacity:.6;margin-left:2px">✕</a></span>${S.plPick===i?`<div class="panel" style="position:absolute;z-index:20;top:26px;left:0;padding:10px;width:300px;box-shadow:0 8px 24px rgba(0,0,0,.15)">${pDots(x.color,'pPickSet')}</div>`:''}</span>`).join('')}
