function pCodeMig(){try{pLegInit();if(PLAN.v3)return;const map={};PLEG.forEach(x=>{const a=oAbbr(x.name);if(a&&a!==x.code&&!PLEG.some(y=>y!==x&&y.code===a)&&!Object.values(map).includes(a)){map[x.code]=a}});const rp=v=>String(v||'').split('+').map(t=>map[t]||t).join('+');const rpu=v=>String(v||'').replace(/(^|\s)([A-ZŠČŽ][A-ZŠČŽ0-9]{0,5})(?=\s+\d)/g,(m,sp,c)=>sp+(map[c]||c));['own','koop'].forEach(g=>(PLAN[g]||[]).forEach(r=>{r.c=r.c.map(rp);Object.keys(r.d||{}).forEach(k=>r.d[k]=rp(r.d[k]))}));if(UREH)Object.keys(UREH).forEach(n=>{if(n==='_v2')return;Object.keys(UREH[n]).forEach(k=>UREH[n][k]=rpu(UREH[n][k]))});PLEG.forEach(x=>{if(map[x.code])x.code=map[x.code]});PLAN.v3=true}catch(x){}}
