 let lastM=-1;const hdr=W.map(w=>{const m=pD(pAdd(w,3)).getUTCMonth();const show=m!==lastM;lastM=m;const hd=[0,1,2,3,4].map(i=>pAdd(w,i)).filter(uHol);return `<div class="h" style="font-size:9px;line-height:1.25${hd.length?';color:var(--bad);font-weight:700':''}" ${hd.length?`title="${hd.map(d=>uHol(d)+' '+pDM(d)).join(', ')}"`:''}>${show?'<b>'+MNS[m].slice(0,3)+'</b>':'&nbsp;'}<br>${pWk(w)}</div>`}).join('');
