   if(v==='DOP'||v==='ODS'||v==='BOL'){v==='DOP'?x.dop++:v==='BOL'?x.bol++:x.ods++;if(wk&&!hol&&inR)x.abs+=8}else if(v==='PRA'||(!v&&hol)){x.pra++;if(wk&&!hol&&inR)x.abs+=8}
