 <div class="grid4 mt">${box('Dopusti',uDn(T.dop)+' · '+T.dop*8+' ur',mon.filter(x=>x.dop).map(x=>x.n+' '+x.dop).join(', '),W)}${box('Odsotnosti',uDn(T.ods)+' · '+T.ods*8+' ur',mon.filter(x=>x.ods).map(x=>x.n+' '+x.ods).join(', '),W)}${OB.map(([k,o])=>box(k==='?'?'Režija brez oznake objekta':k+' · '+uObjName(k),f1(o.h+o.r)+' ur',(o.r?'od tega režija '+f1(o.r)+' · ':'')+f1(o.md)+' človek-dni · '+o.m.size+' '+(o.m.size===1?'monter':o.m.size<5&&o.m.size>1?'monterji':'monterjev'),pCol(k)?`border-left:4px solid ${pCol(k).bg}`:'')).join('')}${T.R?box('Režijske ure',f1(T.R)+' ur','',''):''}</div>
