function r_n(g,ri){return (PLAN[g][ri].n||'').split(' · ')[0]||'monter '+(ri+1)}
function planSet(g,ri,iso,v){v=v.trim().toUpperCase();if(v==='ODSOTEN'||v==='ODSOTNA')v='ODS';if(v==='DOPUST')v='DOP';if(v==='PRAZNIK')v='PRA';if(/^BOLNI[ŠS]K[AO]$/.test(v))v='BOL';v=v.replace(/,/g,'.').replace(/\s+/g,' ');const r=PLAN[g][ri];const old=pGet(r,iso);r.d=r.d||{};r.d[iso]=v;const k=Math.round((pD(iso)-pD(PBASE))/864e5);if(k>=0&&k<7)r.c[k]=v;log('Plan ekip, '+r_n(g,ri),pDayLab(iso)+'.: '+(old||'prazno')+' → '+(v||'prazno'));save();render();if(cCodes(v).includes('R'))toast('Režijski uri dodaj oznako objekta, npr. »R-WC 2« za WESTLINK Campus. Brez oznake se ne šteje v stroške nobenega objekta.');else if(cConf(v))toast('Opozorilo: monter je isti dan na dveh objektih brez vpisanih ur, štejem 4 + 4. Za drugačno delitev vpiši npr. »WC 6 HK 2«.')}
function parseU(v){const out={};let tot=0;String(v).toUpperCase().replace(/(?:^|\s)([A-ZŠČŽ][A-ZŠČŽ0-9]{0,5}(?:-[A-ZŠČŽ][A-ZŠČŽ0-9]{0,5})?)\s+(\d+(?:[.,]\d+)?)/g,(m,c,h)=>{const x=parseFloat(h.replace(',','.'));out[c]=(out[c]||0)+x;tot+=x;return m});return {out,tot}}
// Režijska ura mora imeti oznako objekta: R-WC = režijska ura na WESTLINK Campus
const isR=c=>/^R(-|$)/.test(c);const rObj=c=>c.startsWith('R-')?c.slice(2):'';const rSum=o=>Object.entries(o).reduce((a,[k,h])=>a+(isR(k)?h:0),0);const baseC=c=>isR(c)?rObj(c):c;
