function cCodes(v){v=String(v||'').toUpperCase().trim();if(!v||PABS.includes(v))return [];return v.split(/[+\s]+/).filter(t=>/^[A-ZŠČŽ][A-ZŠČŽ0-9]{0,5}(-[A-ZŠČŽ][A-ZŠČŽ0-9]{0,5})?$/.test(t))}
function cHrs(v){v=String(v||'').toUpperCase().trim();if(!v||PABS.includes(v))return {out:{},tot:0};if(/\d/.test(v))return parseU(v);const cs=cCodes(v);const out={};cs.forEach(c=>out[c]=(out[c]||0)+Math.round(8/cs.length*10)/10);return {out,tot:cs.length?Object.values(out).reduce((a,b)=>a+b,0):0}}
