function uKey(r){return r.n&&r.n.trim()?r.n.trim():'#'+PLAN.own.indexOf(r)}
function uNm(r){return r.n&&r.n.trim()?r.n.trim():'monter '+(PLAN.own.indexOf(r)+1)}
const SIHC={};function siEaster(y){const a=y%19,b=Math.floor(y/100),c=y%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),mo=Math.floor((h+l-7*m+114)/31),da=((h+l-7*m+114)%31)+1;return pIso(new Date(Date.UTC(y,mo-1,da)))}
// Dela prosti dnevi po ZPDPD (vir: gov.si/teme/drzavni-prazniki)
function siHol(y){if(SIHC[y])return SIHC[y];const o={};[['01-01','novo leto'],['01-02','novo leto'],['02-08','Prešernov dan, slovenski kulturni praznik'],['04-27','dan upora proti okupatorju'],['05-01','praznik dela'],['05-02','praznik dela'],['06-25','dan državnosti'],['08-15','Marijino vnebovzetje'],['10-31','dan reformacije'],['11-01','dan spomina na mrtve'],['12-25','božič'],['12-26','dan samostojnosti in enotnosti']].forEach(([d,n])=>o[y+'-'+d]=n);const ea=siEaster(y);o[ea]='velikonočna nedelja';o[pAdd(ea,1)]='velikonočni ponedeljek';o[pAdd(ea,49)]='binkoštna nedelja';return SIHC[y]=o}
