const SIINFO={'06-08':'dan Primoža Trubarja','08-17':'priključitev Prekmurja in združitev prekmurskih Slovencev z matičnim narodom','09-15':'priključitev Primorske k matični domovini','09-23':'dan slovenskega športa','10-25':'dan suverenosti','11-10':'dan znanosti','11-23':'dan Rudolfa Maistra'};
function uHol(iso){return siHol(+iso.slice(0,4))[iso]||''}
function uInfo(iso){return SIINFO[iso.slice(5)]||''}
function saveAll(w){const el=document.activeElement;if(el&&el.blur&&/INPUT|SELECT|TEXTAREA/.test(el.tagName))el.blur();save();log(w,'vnosi shranjeni');toast(w+': vse spremembe so shranjene')}
function uWeek(){return S.pw||PBASE}
function uMont(w){return PLAN.own.filter(r=>pUsed(r)&&pVis(r,w))}
function uVal(r,iso){if(r.end&&iso>=r.end)return {v:'',pl:false,off:true};const pv=pGet(r,iso);if(!pv){const wd=pD(iso).getUTCDay();if(wd>0&&wd<6&&uHol(iso))return {v:'PRA',pl:true};return {v:'',pl:false}}if(PABS.includes(pv))return {v:pv,pl:true};const h=cHrs(pv);return {v:Object.entries(h.out).map(([c,x])=>c+' '+String(x).replace('.',',')).join(' '),pl:true}}
function uY(){return pYear()}
function uM(){return S.pm||(S.pw||PBASE).slice(0,7)}
function uDays(){return pDays()}
function uFrom(){return pFrom()}
function uNav(k){if(S.pv==='y')S.uy=uY()+k;else if(S.pv==='m'){const m=uM();S.um=pIso(new Date(Date.UTC(+m.slice(0,4),+m.slice(5,7)-1+k,1))).slice(0,7)}else S.uw=pAdd(uWeek(),7*k);render()}
function uView(v){if(v==='m')S.um=S.pv==='y'?uY()+'-'+uM().slice(5,7):uWeek().slice(0,7);if(v==='y')S.uy=+(S.pv==='m'?uM():uWeek()).slice(0,4);if(v==='w'&&S.pv!=='w'){const base=S.pv==='m'?uM()+'-01':uY()+'-'+uM().slice(5,7)+'-01';if(uWeek().slice(0,7)!==base.slice(0,7))S.uw=pMon(base)}S.pv=v;render()}
function uLabel(){return pLabel()}
function uLab(v){return v==='ODS'?'odsoten':v==='DOP'?'dopust':v==='PRA'?'praznik':v==='BOL'?'bolniška':v}
function uAbs(M,days){let dop=0,pra=0,bol=0;days.forEach(iso=>M.forEach(r=>{const v=uVal(r,iso).v;if(v==='DOP'||v==='ODS')dop++;else if(v==='PRA')pra++;else if(v==='BOL')bol++}));return {dop,pra,bol}}
const uDn=n=>n+(n===1?' dan':n===2?' dneva':n>2&&n<5?' dnevi':' dni');
function uMonthSum(r,y,m){let t=0;const n=new Date(Date.UTC(y,m+1,0)).getUTCDate();for(let d=1;d<=n;d++){const iso=y+'-'+String(m+1).padStart(2,'0')+'-'+String(d).padStart(2,'0');t+=parseU(uVal(r,iso).v).tot}return t}
const f1=x=>String(Math.round(x*10)/10).replace('.',',');
function uBtns(){const v=S.pv||'w';return `<div class="flex" style="gap:4px">${[['w','Teden'],['m','Mesec'],['y','Leto']].map(x=>`<button class="sm ${v===x[0]?'pri':''}" onclick="uView('${x[0]}')">${x[1]}</button>`).join('')}</div>`}
function pUre(){
 const head=`<div class="between mb"><div><h1>Ure</h1></div><div class="flex"><button class="pri" onmousedown="event.preventDefault()" onclick="saveAll(this.dataset.w)" data-w="Ure">Shrani</button><button onclick="expUreX()">Izvozi v Excel</button><button onclick="expUreC()" title="Za računovodstvo">Izvozi v CSV</button><button onclick="expUreP()">Ustvari PDF</button></div></div>
 <div class="between mb" style="align-items:center"><div class="flex" style="align-items:center;gap:6px"><button class="sm" onclick="uNav(-1)" aria-label="Nazaj">‹</button><b style="min-width:180px;text-align:center">${uLabel()}</b><button class="sm" onclick="uNav(1)" aria-label="Naprej">›</button></div>${uBtns()}</div>`;
 const byObj={};const M=uMont(uFrom());
 if(S.pv==='y'){const y=uY();const gt='120px repeat(12,minmax(48px,1fr)) 60px';
  const rows=M.map(r=>{let t=0;const c=MNS.map((n,m)=>{const h=uMonthSum(r,y,m);t+=h;return `<div class="cell" onclick="S.pv='m';S.um='${y}-${String(m+1).padStart(2,'0')}';render()" style="cursor:pointer;background:var(--panel2)">${h?f1(h):''}</div>`}).join('');return `<div class="small">${uNm(r)}</div>${c}<div class="cell" style="font-weight:700;background:var(--b2);color:var(--ink);border:1px solid var(--line2)">${f1(t)}</div>`}).join('');
  return head+`<div class="panel pad"><div class="tw"><div class="ug" style="grid-template-columns:${gt};min-width:820px"><div class="small muted">monter</div>${MNS.map(n=>`<div class="h">${n.slice(0,3)}</div>`).join('')}<div class="h">Σ</div></div><div class="ug" style="grid-template-columns:${gt};min-width:820px;margin-top:3px">${rows||'<div class="small muted" style="grid-column:1/-1">V Planu ekip ni vpisanih monterjev.</div>'}</div></div><div class="small muted mt">Ure po mesecih. Klik na mesec ga odpre.</div>${(()=>{const b={};uPeriodDays().forEach(iso=>M.forEach(r=>Object.entries(parseU(uVal(r,iso).v).out).forEach(([k,h])=>b[k]=(b[k]||0)+h)));return uBoxes(b,uAbs(M,uPeriodDays()))})()}</div>`}
 const D=uDays();const MM=S.pv==='m';const gt=MM?`120px repeat(${D.length},minmax(40px,1fr)) 56px`:'120px repeat(7,minmax(70px,1fr)) 56px';const mw=MM?176+D.length*42:700;
 let rows=M.map(r=>{let t=0;const cells=D.map(iso=>{const x=uVal(r,iso);if(x.off)return '<div></div>';const p=parseU(x.v);t+=p.tot;Object.entries(p.out).forEach(([k,h])=>byObj[k]=(byObj[k]||0)+h);const white=x.v==='ODS'||x.v==='DOP'||x.v==='PRA';const we=[0,6].includes(pD(iso).getUTCDay());const lab=MM?(white?x.v:x.v):uLab(x.v);return `<input class="cell ${x.pl?'planned':''}" style="background:${white?'#FFFFFF':we?'var(--line)':'var(--panel2)'};${white?'color:#4A5866;':''}${MM?'font-size:10px;padding:5px 0':''}" value="${lab}" onchange="ureSet(${PLAN.own.indexOf(r)},'${iso}',this.value)" aria-label="${r.n} ${pDayLab(iso)}">`}).join('');return `<div class="small">${uNm(r)}</div>${cells}<div class="cell" style="font-weight:700;background:var(--b2);color:var(--ink);border:1px solid var(--line2)">${f1(t)}</div>`}).join('');
 return head+`<div class="panel pad"><div class="tw"><div class="ug" style="grid-template-columns:${gt};min-width:${mw}px"><div class="small muted">monter</div>${D.map(iso=>`<div class="h"${MM?' style="font-size:10px"':''}>${MM?DN[pD(iso).getUTCDay()].slice(0,2)+'<br>'+pD(iso).getUTCDate():pDayLab(iso)}</div>`).join('')}<div class="h">Σ</div></div><div class="ug" style="grid-template-columns:${gt};min-width:${mw}px;margin-top:3px">${rows||'<div class="small muted" style="grid-column:1/-1;padding:8px 0">V Planu ekip ni vpisanih monterjev.</div>'}</div></div>
 <div class="flex small muted mt"><span><span style="display:inline-block;width:14px;height:10px;border:1px dashed var(--line2);vertical-align:-1px"></span> iz Plana ekip</span><span>R = režijska ura</span><span>Tipkaj npr. »WC 8« ali »WC 4 HK 4«, prazno vrne vrednost iz plana</span></div>
 ${uBoxes(byObj,uAbs(M,D))}</div>`;
}
function uBoxes(byObj,ab){ab=ab||{dop:0,pra:0};return `<div class="grid4 mt">${Object.entries(byObj).filter(([k])=>k!=='R').map(([k,x])=>`<div class="met"><div class="l">${pLegHas(k)?k:oAbbr(k)} · ${uObjName(k)}</div><div class="v">${f1(x)} ur</div></div>`).join('')}${byObj.R?`<div class="met warn"><div class="l">Režijske ure</div><div class="v">${f1(byObj.R)} ur</div></div>`:''}<div class="met" style="background:#FFFFFF;border:1px solid var(--line2)"><div class="l">Dopusti in odsotnosti</div><div class="v">${uDn(ab.dop)} · ${ab.dop*8} ur</div></div><div class="met" style="background:#FFFFFF;border:1px solid var(--line2)"><div class="l">Prazniki</div><div class="v">${uDn(ab.pra)} · ${ab.pra*8} ur</div></div></div>`}
function uPeriodDays(){if(S.pv==='y'){const y=uY();const out=[];for(let d=y+'-01-01';pD(d).getUTCFullYear()===y;d=pAdd(d,1))out.push(d);return out}return uDays()}
function ureSet(ri,iso,v){ureMig();const r=PLAN.own[ri];v=v.trim().toUpperCase();if(v==='ODSOTEN'||v==='ODSOTNA')v='ODS';if(v==='DOPUST')v='DOP';if(v==='PRAZNIK')v='PRA';const K=uKey(r);UREH[K]=UREH[K]||{};if(v==='')delete UREH[K][iso];else UREH[K][iso]=v;log('Ure, '+uNm(r),pDayLab(iso)+'.: '+(v||'iz plana'));save();render()}
function uConfirm(){ureMig();const w=uWeek();let n=0;uMont(w).forEach(r=>{for(let i=0;i<6;i++){const iso=pAdd(w,i);const x=uVal(r,iso);if(x.pl&&x.v){(UREH[uKey(r)]=UREH[uKey(r)]||{})[iso]=x.v;n++}}});log('Ure','teden '+uLabel()+' potrjen');save();render();toast('Teden potrjen'+(n?', '+n+' vnosov prevzetih iz plana':''))}
let PLIST=null;const PCAT=['Stranke','Projektanti','Kooperanti','Podizvajalci','Dobavitelji'];
function plInit(){if(PLIST)return;PLIST=[['SGP Graditelj d.d.','Glavni izvajalec','Stranke'],['GARNOL d.o.o.','Glavni izvajalec','Stranke'],['CORWIN SK a.s.','Glavni izvajalec','Stranke'],['Miha Kušar','Investitor, fizična oseba','Stranke'],['Kooperant Miha','Kooperant','Kooperanti'],['Gips Tim s.p.','Kooperant','Kooperanti'],['Kalcer d.o.o.','Dobavitelj','Dobavitelji'],['Elektro Makše d.o.o.','Podizvajalec','Podizvajalci']].map(x=>({n:x[0],role:x[1],cat:x[2]}))}
function plLinks(n){const k=n.split(' ')[0].toLowerCase();const o=Object.values(OBJ).filter(x=>canSee(x)&&x.client&&x.client.split(' ')[0].toLowerCase()===k).length;const pp=POVP.filter(x=>x.nar&&x.nar.split(' ')[0].toLowerCase()===k).length;return [o?o+(o===1?' objekt':' objekti'):'',pp?pp+(pp===1?' ponudba':' ponudbe'):''].filter(Boolean).join(' · ')||'—'}
function pPartnerji(){
 if(S.partner)return partnerCard();
 plInit();const f=S.pcat||'Vsi';const L=PLIST.map((r,i)=>[r,i]).filter(([r])=>f==='Vsi'||r.cat===f).sort((a,b)=>a[0].n.localeCompare(b[0].n,'sl'));
 return `<div class="between mb"><div><h1>Partnerji</h1><div class="sub">Ena baza za stranke, projektante, kooperante, podizvajalce in dobavitelje</div></div><button class="pri" onclick="S.padd=1;render()">Dodaj partnerja</button></div>
 ${S.padd?`<div class="panel pad mb"><div class="flex" style="gap:8px;align-items:center"><input id="pa_n" placeholder="naziv, npr. Gradis d.o.o." style="width:260px"><select id="pa_c">${PCAT.map(c=>`<option ${c===(f==='Vsi'?'Stranke':f)?'selected':''}>${c}</option>`).join('')}</select><input id="pa_r" placeholder="vloga, npr. glavni izvajalec" style="width:220px"><button class="pri" onclick="plAdd()">Dodaj</button><button onclick="S.padd=0;render()">Prekliči</button></div></div>`:''}
 <div class="pills">${['Vsi',...PCAT].map(c=>`<a class="${f===c?'on':''}" onclick="S.pcat='${c}';render()">${c}</a>`).join('')}</div>
 <div class="panel"><table class="t"><thead><tr><th>Naziv</th><th>Vloga</th><th>Povezave</th><th></th></tr></thead><tbody>${L.length?L.map(([r,i])=>S.plEd===i?`<tr style="background:var(--panel2)"><td><input id="pe_n" value="${r.n.replace(/"/g,'&quot;')}" style="width:100%" onkeydown="if(event.key==='Enter')plSave(${i});if(event.key==='Escape'){S.plEd=null;render()}"></td><td><input id="pe_r" value="${String(r.role||'').replace(/"/g,'&quot;')}" style="width:100%;margin-bottom:4px" onkeydown="if(event.key==='Enter')plSave(${i})"><select id="pe_c" style="width:100%">${PCAT.map(c=>`<option ${c===r.cat?'selected':''}>${c}</option>`).join('')}</select></td><td class="small muted">${plLinks(r.n)}</td><td style="text-align:right;white-space:nowrap"><button class="sm" onclick="S.plEd=null;render()">Prekliči</button> <button class="sm pri" onclick="plSave(${i})">Shrani</button></td></tr>`:`<tr class="click" onclick="S.partner=${JSON.stringify(r.n).replace(/"/g,'&quot;')};S.prole=${JSON.stringify(r.role).replace(/"/g,'&quot;')};render()"><td style="font-weight:500">${r.n}</td><td>${r.role}</td><td class="small muted">${plLinks(r.n)}</td><td style="text-align:right;white-space:nowrap"><button class="sm" onclick="event.stopPropagation();S.plEd=${i};render();setTimeout(()=>{const el=document.getElementById('pe_n');if(el)el.focus()},0)" title="Uredi partnerja">Uredi</button> <button class="sm" onclick="event.stopPropagation();plDel(${i})" title="Izbriši partnerja">Izbriši</button></td></tr>`).join(''):'<tr><td colspan="4" class="muted">V tej skupini še ni partnerjev.</td></tr>'}</tbody></table></div>`;
}
function plAdd(){const n=document.getElementById('pa_n').value.trim(),c=document.getElementById('pa_c').value,r=document.getElementById('pa_r').value.trim();if(!n){toast('Vpiši naziv partnerja');return}if(PLIST.some(x=>x.n.toLowerCase()===n.toLowerCase())){toast('Partner '+n+' že obstaja');return}PLIST.push({n,cat:c,role:r||c.replace(/i$/,'').replace(/e$/,'a')});S.padd=0;log('Partnerji','dodan '+n);save();render();toast('Partner '+n+' dodan')}
function plSave(i){const x=PLIST[i];const n=document.getElementById('pe_n').value.trim(),r=document.getElementById('pe_r').value.trim(),c=document.getElementById('pe_c').value;if(!n){toast('Naziv ne sme biti prazen');return}if(PLIST.some((y,k)=>k!==i&&y.n.toLowerCase()===n.toLowerCase())){toast('Partner '+n+' že obstaja');return}
 const ch=[];if(x.n!==n){ch.push('naziv '+x.n+' → '+n);const d=Object.assign({},PDEF[x.n]||{},PART[x.n]||{});if(Object.keys(d).length)PART[n]=d;delete PART[x.n]}if(x.role!==r)ch.push('vloga '+(x.role||'—')+' → '+(r||'—'));if(x.cat!==c)ch.push('skupina '+x.cat+' → '+c);x.n=n;x.role=r;x.cat=c;S.plEd=null;if(ch.length)log('Partnerji',ch.join(', '));save();render();toast(ch.length?'Partner shranjen':'Ni sprememb')}
async function plDel(i){const x=PLIST[i];if(!await uiConfirm('Izbrišem partnerja '+x.n+'? Izbrišejo se tudi podatki na njegovi kartici. Objekti in ponudbe ostanejo.'))return;PLIST.splice(i,1);delete PART[x.n];log('Partnerji','izbrisan '+x.n);save();render();toast('Partner izbrisan')}
