const KOOPLINK={W111:'Stena W111',W112:'Stena W112',W115:'Stena W115 in W116',W116:'Stena W115 in W116',W623:'Gips obloga z izolacijo',W611:'Lepljenje gips plošč',D112:'Montaža gips stropa',D113:'Montaža gips stropa',KCS:'Armstrong Board'};
const BANDLINK='Bandažiranje Q2';
function kalcerSup(){return Object.values(SUPC).find(c=>/kalcer/i.test(c.name))||null}
function kalcerIdx(){const c=kalcerSup();if(!c)return null;if(c._ix&&c._ixr===c.rows)return c._ix;const ix={},cnt={};c.rows.forEach(r=>{const k=cNorm(r[2]);cnt[k]=(cnt[k]||0)+1;ix[k+'#'+cnt[k]]=r});c._ix=ix;c._ixr=c.rows;return ix}
function kPrice(name){const L=KLINK[name];const ix=kalcerIdx();if(!L||!ix)return null;const r=ix[cNorm(L[0])+'#'+(L[1]||1)];if(!r)return null;const p=cNum(r[4]);return p==null?null:{p:p*(L[2]||1),row:r,note:L[3]||''}}
function kItem(it){const k=kPrice(it[0]);const p=k?k.p:it[3];return {it,p,k,net:p*(1-it[4]/100)*(1-it[5]/100),old:it[3]}}
function kPlate(t){const ix=kalcerIdx();const r=ix&&ix[cNorm(PLATEN[t])+'#1'];const p=r?cNum(r[4]):null;return p!=null?{p,ok:true}:{p:PLATE[t],ok:false}}
function rangeMid(t){if(typeof t==='number')return t;const m=String(t).match(/^(\d+(?:[.,]\d+)?)\s*[–-]\s*(\d+(?:[.,]\d+)?)$/);if(m)return (cNum(m[1])+cNum(m[2]))/2;return cNum(t)}
function koopLink(code){const n=KOOPLINK[code];const r=n&&CEN_KOOP.find(x=>cNorm(x[0])===cNorm(n));if(r){const v=rangeMid(r[2]);if(v!=null)return {v,src:r[0]+' · '+r[2]+(String(r[2]).match(/[–-]/)?' → sredina '+e(v):''),ok:true}}return SYSKOOP[code]!=null?{v:SYSKOOP[code],src:'postavke »'+(n||code)+'« ni v ceniku kooperantov, vzeta stara vrednost',ok:false}:null}
function bandLink(){const r=CEN_KOOP.find(x=>cNorm(x[0])===cNorm(BANDLINK));if(r){const v=rangeMid(r[2]);if(v!=null)return {v,src:r[0]+' · '+r[2]+(String(r[2]).match(/[–-]/)?' → sredina '+e(v):''),ok:true}}return {v:3.25,src:'postavke »'+BANDLINK+'« ni v ceniku kooperantov, vzeto 3,25',ok:false}}
function sysNet(it){return kItem(it).net}
function sysDetail(i){const r=SYS[i];const code=r[0];const nm=SYSMAPN[r[1]];const items=nm?KNORM[nm]:null;const T=SYSTECH[sysTechKey(i)];const side=SYSSIDES[code]!=null?SYSSIDES[code]:2;const KL=koopLink(code);const koop=KL?KL.v:null;const BL=bandLink();const KS=kalcerSup();const KI=items?items.map(kItem):[];const miss=KI.filter(x=>!x.k);const pl={GKB:kPlate('GKB'),GKBI:kPlate('GKBI'),GKF:kPlate('GKF')};
 let mat=null,plates=0;if(items){mat=KI.reduce((a,x)=>a+x.it[1]*x.net,0);plates=items.filter(it=>/PLOŠČA KNAUF GKB/.test(it[0])).reduce((a,it)=>a+it[1],0)}
 const disc=0.75*0.95;const var_=[['Navadna',0,r[3]],['Vlagoodp.',plates*(pl.GKBI.p-pl.GKB.p)*disc,r[4]],['Ognjevarna',plates*(pl.GKF.p-pl.GKB.p)*disc,r[5]]];
 const band=side*BL.v;const lab=(t,sub,warn)=>t+`<div class="small ${warn?'':'muted'}" style="font-weight:400;${warn?'color:var(--warn)':''}">${sub}</div>`;const tr=(l,vals,cls)=>`<tr${cls?` class="${cls}"`:''}><td>${l}</td>${vals.map(v=>`<td class="n">${v}</td>`).join('')}</tr>`;
 const calc=mat!=null?var_.filter((v,k)=>k===0||plates>0).map(([n,add,sale])=>{const m=(mat+add)*1.05;const c=m+(koop||0)+band;return {n,mn:mat+add,m,c,sale,d:sale?sale-c:null}}):null;
 return `<div class="panel pad mb"><div class="between" style="align-items:center"><h2 style="margin:0">Knauf ${code}</h2><span class="small muted">${r[1]}</span></div>${r[2]?`<div class="small muted">${r[2]}</div>`:''}</div>
 <h2>Tehnični podatki</h2><div class="panel mb">${T?`<div class="tw"><table class="t"><thead><tr><th>Obloga na strani</th><th>EI</th><th>${T.rp!=null?T.rp:'Rw dB'}</th>${T.rows[0][3]!==''?'<th class="n">kg/m²</th>':''}<th class="n">${code==='D112'?'razmak':'max. višina m'}</th></tr></thead><tbody>${T.rows.map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${x[2]}</td>${T.rows[0][3]!==''?`<td class="n">${x[3]}</td>`:''}<td class="n">${x[4]}</td></tr>`).join('')}</tbody></table></div><div class="pad small muted" style="padding-top:6px">${T.h}${/W11|W116/.test(code)?' · Rw za profile CW 50 / 75 / 100':''} · vir: Knauf tehnična mapa, ${T.src}</div>`:'<div class="pad small muted">V Knaufovi tehnični mapi za ta sistem ni podatkov (ni Knauf sistem ali ni v mapi).</div>'}</div>
 <h2>Kalkulacija na m²</h2><div class="panel mb">${calc?`<div class="tw"><table class="t"><thead><tr><th></th>${calc.map(c=>`<th class="n">${c.n}</th>`).join('')}</tr></thead><tbody>
 ${tr(lab('Material Kalcer, neto',KS?'Ceniki › Dobavitelji › '+KS.name+', velja od '+KS.date+(miss.length?' · '+miss.length+' artiklov ni v ceniku, cena iz ponudbe':''):'cenika Kalcer ni, cene iz ponudbe 26-PP05554',!KS||miss.length),calc.map(c=>e(c.mn)))}${tr('+ kalo 5 %',calc.map(c=>e(c.m-c.mn)))}${tr(lab('Delo kooperant',KL?'Ceniki › Kooperanti › '+KL.src:'ni povezave na cenik kooperantov',!KL||!KL.ok),calc.map(()=>koop!=null?e(koop):'—'))}${side?tr(lab('Bandaža Q2 ('+side+'× '+e(BL.v)+')','Ceniki › Kooperanti › '+BL.src,!BL.ok),calc.map(()=>e(band))):''}${tr('<b>Strošek</b>',calc.map(c=>'<b>'+e(c.c)+'</b>'),'sum')}${tr('Prodajna cena (cenik)',calc.map(c=>c.sale?e(c.sale):'—'))}${tr('<b>Razlika</b>',calc.map(c=>c.d==null?'—':`<b class="${c.d>=0?'okline':'badline'}">${e(c.d)} · ${Math.round(c.d/c.sale*100)} %</b>`),'sum')}
 </tbody></table></div><div class="pad small muted" style="padding-top:6px">Normativ Kalcer: ${nm.toLowerCase()}${/W11|W115/.test(code)&&!/75\/1/.test(r[1].replace(' ',''))?'':''}. Vlagoodporna in ognjevarna: plošče GKB zamenjane z GKB-I oz. GKF po ceniku Kalcer (${e(pl.GKB.p)} / ${e(pl.GKBI.p)} / ${e(pl.GKF.p)} €/m² pred popustom${pl.GKB.ok&&pl.GKBI.ok&&pl.GKF.ok?'':', del cen iz starega vira'}). Popust 25 + 5 % po ponudbi 26-PP05554. Ko osvežiš cenik Kalcer ali cenik kooperantov, se kalkulacija preračuna sama.</div>`:'<div class="pad small muted">Za ta sistem ni normativa Kalcer, kalkulacije materiala zato ni.</div>'}</div>
 ${items?`<details class="mb"><summary style="cursor:pointer;font-weight:600;font-size:15px;padding:4px 0">Material po normativu Kalcer (na m²)</summary><div class="panel mt"><div class="tw"><table class="t"><thead><tr><th>Artikel v normativu / v ceniku</th><th class="n">Kol./m²</th><th>em</th><th class="n">Ponudba 3/2026</th><th class="n">Neto €/m²</th></tr></thead><tbody>${KI.map(x=>`<tr><td class="small">${x.it[0]}<div class="${x.k?'muted':''}" style="${x.k?'':'color:var(--warn)'}">${x.k?'→ '+x.k.row[2]+(x.k.note?' · '+x.k.note:''):'ni v ceniku, cena iz ponudbe'}</div></td><td class="n">${String(Math.round(x.it[1]*1000)/1000).replace('.',',')}</td><td>${x.it[2]}</td><td class="n muted">${e(x.old)}</td><td class="n">${e(x.it[1]*x.net)}${x.it[4]!==25||x.it[5]!==5?`<div class="small muted">${x.it[4]}+${x.it[5]} %</div>`:''}</td></tr>`).join('')}<tr class="sum"><td>Skupaj material</td><td></td><td></td><td></td><td class="n">${e(mat)}</td></tr></tbody></table></div><div class="pad small muted" style="padding-top:6px">Neto = cena v trenutnem ceniku × (1 − 25 %) × (1 − 5 %), razen kjer je popust napisan pod zneskom. Količine na m² in popusti iz ponudbe Kalcer 26-PP05554 z dne 11. 3. 2026 (osnova 100 m²). Cene iz trenutnega cenika ${KS?KS.name+', velja od '+KS.date:'— cenik Kalcer ni naložen'}. Cena fco skladišče Kalcer, brez prevoza in razklada.</div></div></details>`:''}
 ${SYSDOS[code]?`<h2>Doseženo na projektih</h2><div class="panel pad mb small">${SYSDOS[code].map(x=>`<div class="between"><span class="muted">${x[0]}</span><span>${e(x[1])} €/m²</span></div>`).join('')}</div>`:''}
 <div class="note">Cene: dobava in montaža, z bandažiranjem Q2, osnova 100 m², izolacija 5 cm, kalo 5 %. Ureja direktor${S.role==='direktor'?'':' (ti si v vlogi za ogled)'}.</div>${S.role==='direktor'||S.role==='admin'?'<button class="mt" onclick="toast(\'Nov cenik velja od izbranega datuma, stare ponudbe ostanejo nespremenjene\')">Nov cenik od datuma</button>':''}`}
