function rpHours(){pLegInit();const y=+PBASE.slice(0,4);const out={};const M=PLAN.own.filter(r=>r.n&&r.n.trim());for(let d=y+'-01-01';pD(d).getUTCFullYear()===y;d=pAdd(d,1)){M.forEach(r=>{const x=uVal(r,d);if(!x.v)return;Object.entries(parseU(x.v).out).forEach(([k,h])=>out[k]=(out[k]||0)+h)})}return out}
function rpObjHours(o,H){const nm=o.name.split(',')[0];const cs=new Set([o.code,...(PLEG||[]).filter(x=>x.name===nm).map(x=>x.code)]);let h=0;cs.forEach(c=>h+=H[c]||0);return h}
function rpData(){const H=rpHours();return Object.values(OBJ).map(o=>{const full=o.full&&dataOf(o.id);let obr,cost,mat=0,koop=0,lastne=0,phase,nk=0;if(full){const d=dataOf(o.id);const t=sitTotals(o.id);obr=t.tot;cost=costSum(o.id);mat=dobaSum(o.id);koop=koopSum(o.id);const C=costFor(o.id);lastne=cost-mat-koop;nk=new Set((d.KOOP||[]).map(k=>k.k)).size;const st=d.SITST||{n:1,st:'v pripravi'};phase=o.done?'končan':st.n+'. situacija · '+st.st}else{obr=+o.obr||0;cost=o.izid!=null?obr*(1-o.izid/100):null;phase=o.done?'končan':(o.sit||o.status||'')}
 return {o,obr,cost,res:cost==null?null:obr-cost,mat,koop,lastne,nk,phase,h:rpObjHours(o,H),est:!full}})}
function rpType(t){t=String(t);if(/diamant/i.test(t))return 'Diamant';if(/GKF-?I|GKFI|DFH2/i.test(t))return 'GKF-I';if(/GKF|ognj|požar|pozar|\bEI\s?\d{2,3}|\bF\s?\d{2}\b|fireboard/i.test(t))return 'GKF';if(/GKB-?I|GKBI|\bH2\b|vlago|impregn/i.test(t))return 'GKB-I';return 'GKB'}
function rpThick(t){t=String(t);let m=t.match(/(\d{2,3})\s*\/\s*(\d{2,3})/);if(m)return +m[2];m=t.match(/deb(?:eline|\.)?\s*(\d{1,2}(?:[,.]\d)?)\s*cm/i);if(m)return Math.round(parseFloat(m[1].replace(',','.'))*10);m=t.match(/\b(75|100|125|150|155|205|255)\s*mm/);if(m)return +m[1];return null}
function rpCenik(code,th,type){const rows=SYS.map((r,i)=>[r,i]).filter(([r])=>r[0]===code);if(!rows.length)return null;let row=rows[0][0];if(th){const f=rows.find(([r])=>{const m=String(r[1]).match(/\/(\d+)/);return m&&+m[1]===th});if(f)row=f[0]}const col=type==='GKB-I'?4:/GKF/.test(type)?5:(type==='GKB'||type==='')?3:null;if(col==null)return null;return row[col]||null}
const RPARCH=MSD.rparch||[];
function rpSys(){const G={};RPARCH.forEach(([code,th,ty,pr,q,obj])=>{if(/^(D|KCS)/.test(code))th=null;const k=code+'|'+(th||'')+'|'+ty;G[k]=G[k]||{code,th,ty,q:0,v:0,min:1e9,max:0,obj:new Set(),n:0};G[k].n++;G[k].q+=q;G[k].v+=q*pr;G[k].min=Math.min(G[k].min,pr);G[k].max=Math.max(G[k].max,pr);G[k].obj.add(obj)});Object.values(OBJ).filter(o=>o.full&&dataOf(o.id)).forEach(o=>{const d=dataOf(o.id);const rate=o.rate||0;(d.SIT||[]).forEach(r=>{const m=String(r[1]).match(/\b(W\s?1(?:1[1-6])|W6\d{2}|D11[1-3]|KCS|Armstrong|Ecophon)\b/i);if(!m)return;const code=m[1].replace(/\s/g,'').toUpperCase();const th=/^(D|KCS)/.test(code)?null:rpThick(r[1]);const ty=code==='KCS'?'':rpType(r[1]);const k=code+'|'+(th||'')+'|'+ty;const q=(r[5]||[]).reduce((a,b)=>a+b,0)+(+r[6]||0);const pr=r[4]*(1-rate);G[k]=G[k]||{code,th,ty,q:0,v:0,min:1e9,max:0,obj:new Set(),n:0};G[k].n++;if(q>0){G[k].q+=q;G[k].v+=q*pr}G[k].min=Math.min(G[k].min,pr);G[k].max=Math.max(G[k].max,pr);G[k].obj.add(o.name.split(',')[0])})});return G}
const RPC={b:'#2a78d6',o:'#eb6834',a:'#1baf7a',y:'#eda100'};
function rpDonut(parts){const tot=parts.reduce((a,p)=>a+p[1],0)||1;let a0=-Math.PI/2;const R=70,r0=44,cx=90,cy=90;const segs=parts.filter(p=>p[1]>0).map(p=>{const a1=a0+2*Math.PI*p[1]/tot;const gap=0.012;const s=a0+gap,e2=a1-gap;const large=e2-s>Math.PI?1:0;const P=(rr,a)=>[cx+rr*Math.cos(a),cy+rr*Math.sin(a)];const [x1,y1]=P(R,s),[x2,y2]=P(R,e2),[x3,y3]=P(r0,e2),[x4,y4]=P(r0,s);a0=a1;return `<path d="M${x1},${y1} A${R},${R} 0 ${large} 1 ${x2},${y2} L${x3},${y3} A${r0},${r0} 0 ${large} 0 ${x4},${y4} Z" fill="${p[2]}"><title>${p[0]}: ${e(p[1])} € (${Math.round(p[1]/tot*100)} %)</title></path>`}).join('');
 return `<div style="display:flex;gap:18px;align-items:center;flex-wrap:wrap"><svg viewBox="0 0 180 180" width="170" height="170" role="img" aria-label="Struktura stroškov">${segs}<text x="90" y="86" text-anchor="middle" style="font-size:11px;fill:var(--ink3)">stroški</text><text x="90" y="103" text-anchor="middle" style="font-size:14px;font-weight:600;fill:var(--ink)">${e0(tot)} €</text></svg><div class="small" style="display:grid;gap:6px">${parts.map(p=>`<div style="display:flex;align-items:center;gap:8px"><span style="width:10px;height:10px;border-radius:2px;background:${p[2]};flex:none"></span><span style="min-width:150px">${p[0]}</span><b>${e0(p[1])} €</b><span class="muted">${Math.round(p[1]/tot*100)} %</span></div>`).join('')}</div></div>`}
function rpBars(rows){const mx=Math.max(1,...rows.map(r=>Math.max(r.obr,r.cost||0)));return `<div class="small" style="display:grid;grid-template-columns:150px 1fr;gap:6px 10px;align-items:center">${rows.map(r=>`<div style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${r.o.name}">${r.o.name.split(',')[0]}</div><div><div title="Obračunano ${e(r.obr)} €" style="height:9px;border-radius:0 4px 4px 0;background:${RPC.b};width:${r.obr/mx*100}%;margin-bottom:2px"></div><div title="Stroški ${r.cost==null?'ni podatka':e(r.cost)+' €'}${r.est?' (ocena)':''}" style="height:9px;border-radius:0 4px 4px 0;background:${RPC.o};width:${(r.cost||0)/mx*100}%;${r.est?'opacity:.55':''}"></div></div>`).join('')}</div><div class="flex small mt" style="gap:14px"><span><span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:${RPC.b}"></span> obračunano</span><span><span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:${RPC.o}"></span> stroški</span><span class="muted">bledo = ocena iz izida</span></div>`}
function rpKpi(l,v,sub,cls){return `<div class="met ${cls||''}"><div class="l">${l}</div><div class="v" style="font-size:20px">${v}</div>${sub?`<div class="small muted">${sub}</div>`:''}</div>`}
function rpBlock(D,showObj){const act=D.filter(x=>!x.o.done);const obr=D.reduce((a,x)=>a+x.obr,0);const withC=D.filter(x=>x.cost!=null);const cost=withC.reduce((a,x)=>a+x.cost,0);const res=withC.reduce((a,x)=>a+x.res,0);const obrC=withC.reduce((a,x)=>a+x.obr,0);const pog=D.reduce((a,x)=>a+(+x.o.pogodba||0),0);const h=D.reduce((a,x)=>a+x.h,0);const mat=D.reduce((a,x)=>a+x.mat,0);const koop=D.reduce((a,x)=>a+x.koop,0);const nk=D.reduce((a,x)=>a+x.nk,0);const last=D.reduce((a,x)=>a+x.lastne,0);
 return {html:`<div class="grid4 mb">${rpKpi('Projekti',act.length+' aktivnih',D.length-act.length?(D.length-act.length)+' končanih':'')}${rpKpi('Pogodbe',e0(pog)+' €')}${rpKpi('Obračunano',e0(obr)+' €')}${rpKpi('Rezultat',e0(res)+' €',obrC?Math.round(res/obrC*100)+' % marža':'',res>=0?'ok':'warn')}${rpKpi('Stroški',e0(cost)+' €')}${rpKpi('Ure lastnih ekip',e0(h)+' h','leto '+PBASE.slice(0,4))}${rpKpi('Material',e0(mat)+' €','po dobavnicah')}${rpKpi('Kooperanti',e0(koop)+' €',nk+(nk===1?' kooperant':' kooperantov'))}</div>`,parts:[['Material',mat,RPC.b],['Podizvajalci in kooperanti',koop,RPC.o],['Lastne ekipe in ostalo',last,RPC.a]]}}
function expRepP(){const D=rpData();const G=rpSys();const fs='10px';const th=x=>`<th style="text-align:left;border-bottom:1px solid #1F3A5F;padding:3px;background:#F1F3F5;font-size:${fs}">${x}</th>`;const thn=x=>`<th style="text-align:right;border-bottom:1px solid #1F3A5F;padding:3px;background:#F1F3F5;font-size:${fs}">${x}</th>`;const td=(x,n)=>`<td style="text-align:${n?'right':'left'};border-bottom:1px solid #DDE2E7;padding:3px;font-size:${fs}">${x}</td>`;const H3=t=>`<div style="font-weight:700;color:#1F3A5F;font-size:13px;margin:12px 0 6px">${t}</div>`;
 const sys=Object.values(G).sort((a,b)=>a.code.localeCompare(b.code)||(a.th||0)-(b.th||0)||a.ty.localeCompare(b.ty));
 const t1=`<table style="width:100%;border-collapse:collapse"><tr>${th('Sistem')}${th('Debelina')}${th('Plošče')}${thn('Cenik')}${thn('Doseženo')}${thn('Razlika')}${thn('m²')}${th('Objekti')}</tr>${sys.map(g=>{const c=rpCenik(g.code,g.th,g.ty);const a=g.q?g.v/g.q:null;return '<tr>'+td(g.code)+td(g.th?g.th+' mm':'—')+td(g.ty||'—')+td(c?e(c):'—',1)+td(a!=null?e(a):'—',1)+td(c&&a?Math.round((a/c-1)*100)+' %':'—',1)+td(e0(g.q),1)+td([...g.obj].slice(0,3).join(', ')+(g.obj.size>3?' …':''))+'</tr>'}).join('')}</table>`;
 const all=rpBlock(D);const kpi=x=>x.replace(/<div class="met[^"]*"><div class="l">([^<]*)<\/div><div class="v"[^>]*>([^<]*)<\/div>(?:<div class="small muted">([^<]*)<\/div>)?<\/div>/g,(m,l,v,sb)=>`<td style="background:#F1F3F5;padding:7px;border:2px solid #fff;vertical-align:top"><div style="font-size:9px;color:#555">${l}</div><div style="font-weight:700;font-size:13px">${v}</div>${sb?`<div style="font-size:9px;color:#555">${sb}</div>`:''}</td>`).replace(/<div class="grid4 mb">/,'<table style="width:100%;border-collapse:collapse"><tr>').replace(/<\/div>$/,'</tr></table>').replace(/(<\/td>)(<td[^>]*>(?:(?!<td).)*?<\/td>){0}/,'$1');
 const kpiT=h=>{const cells=[...h.matchAll(/<td style="background[\s\S]*?<\/td>/g)].map(m=>m[0]);return `<table style="width:100%;border-collapse:collapse;table-layout:fixed"><tr>${cells.slice(0,4).join('')}</tr><tr>${cells.slice(4).join('')}</tr></table>`};
 const vod=[...new Set(D.map(x=>x.o.vodja))].sort().map(v=>{const Dv=D.filter(x=>x.o.vodja===v);const b=rpBlock(Dv);return H3('Vodja projekta: '+v)+kpiT(kpi(b.html))+`<table style="width:100%;border-collapse:collapse;margin-top:6px"><tr>${th('Objekt')}${th('Faza / situacija')}${thn('Pogodba')}${thn('Obračunano')}${thn('Stroški')}${thn('Rezultat')}${thn('Ure')}</tr>${Dv.map(x=>'<tr>'+td(x.o.name)+td(x.phase)+td(x.o.pogodba?e0(x.o.pogodba):'—',1)+td(e0(x.obr),1)+td(x.cost==null?'—':e0(x.cost)+(x.est?' *':''),1)+td(x.res==null?'—':e0(x.res),1)+td(x.h?e0(x.h):'—',1)+'</tr>').join('')}</table>`}).join('');
 pdfPages('Poročila '+fd(new Date().toISOString().slice(0,10))+'.pdf',[head('POROČILA · DIREKTOR',`<b>Datum:</b> ${fd(new Date().toISOString().slice(0,10))}`)+H3('Analiza poslovanja')+kpiT(kpi(all.html))+vod,H3('Dosežene cene po sistemih, 2026')+t1+`<div style="font-size:9px;color:#555;margin-top:8px">* stroški ocenjeni iz izida. Dosežene cene: situacije v programu in arhiv obračunov 2026, po pogodbenem popustu.</div>`])}
function pPorocila(){
 if(S.role!=='direktor'&&S.role!=='admin')return `<h1>Poročila</h1><div class="panel lock mt"><b>Poročila vidi samo direktor.</b></div>`;
 const D=rpData();const G=rpSys();const all=rpBlock(D);const vod=[...new Set(D.map(x=>x.o.vodja))].sort();
 const sysRows=Object.values(G).sort((a,b)=>a.code.localeCompare(b.code)||(a.th||0)-(b.th||0)||a.ty.localeCompare(b.ty)).map(g=>{const c=rpCenik(g.code,g.th,g.ty);const avg=g.q?g.v/g.q:null;return `<tr><td style="font-weight:500;white-space:nowrap">${g.code}</td><td style="white-space:nowrap">${g.th?g.th+' mm':'<span class="muted">—</span>'}</td><td style="white-space:nowrap">${g.ty||'—'}</td><td class="n">${c?e(c):'—'}</td><td class="n">${avg!=null?e(avg):'—'}${g.min<g.max?`<div class="small muted">${e(g.min)}–${e(g.max)}</div>`:''}</td><td class="n">${c&&avg?`<span class="${avg>=c?'okline':'badline'}">${Math.round((avg/c-1)*100)} %</span>`:'—'}</td><td class="n">${e0(g.q)}</td><td class="small muted">${[...g.obj].slice(0,4).join(', ')}${g.obj.size>4?' in še '+(g.obj.size-4):''}</td></tr>`}).join('');
 const vodBlocks=vod.map(v=>{const Dv=D.filter(x=>x.o.vodja===v);const b=rpBlock(Dv);const P=POVP.filter(p=>p.vodja===v);const ok=P.filter(p=>p.st==='potrjeno').length,zav=P.filter(p=>p.st==='zavrnjeno').length,nep=P.filter(p=>p.st==='nepotrjeno').length;const usp=ok+zav?Math.round(ok/(ok+zav)*100):null;
  const pw=uWeek();const plan={};PLAN.own.filter(r=>r.n).forEach(r=>{for(let i=0;i<7;i++){const val=pGet(r,pAdd(pw,i));cCodes(val).map(baseC).filter(Boolean).forEach(c=>{plan[c]=(plan[c]||0)+1})}});
  return `<div class="panel pad mb"><div class="between" style="align-items:center"><h2 style="margin:0">${v}</h2><span class="small muted">ponudbe: ${P.length} · potrjenih ${ok} · zavrnjenih ${zav} · odprtih ${nep}${usp!=null?' · uspešnost '+usp+' %':''}</span></div><div class="mt">${b.html}</div>
  <div class="tw"><table class="t"><thead><tr><th>Objekt</th><th>Faza / situacija</th><th class="n">Pogodba</th><th class="n">Obračunano</th><th class="n">Stroški</th><th class="n">Rezultat</th><th class="n">Ure</th><th class="n">Plan ta teden</th></tr></thead><tbody>${Dv.map(x=>{const nm=x.o.name.split(',')[0];const cs=new Set([x.o.code,...(PLEG||[]).filter(l=>l.name===nm).map(l=>l.code)]);let pd=0;cs.forEach(c=>pd+=plan[c]||0);return `<tr class="click" onclick="openObj('${x.o.id}')"><td>${x.o.name}</td><td class="small">${x.phase}</td><td class="n">${x.o.pogodba?e0(x.o.pogodba):'—'}</td><td class="n">${e0(x.obr)}</td><td class="n">${x.cost==null?'—':e0(x.cost)+(x.est?' *':'')}</td><td class="n ${x.res==null?'':x.res>=0?'okline':'badline'}">${x.res==null?'—':e0(x.res)}</td><td class="n">${x.h?e0(x.h):'—'}</td><td class="n">${pd?pd+' dni':'—'}</td></tr>`}).join('')}</tbody></table></div></div>`}).join('');
 return `<div class="between mb"><div><h1>Poročila</h1></div><div class="flex"><button onclick="expRepX()">Izvozi Excel</button><button onclick="expRepP()">Ustvari PDF</button></div></div>
 <h2>Analiza poslovanja</h2><div class="panel pad mb">${all.html}<div class="grid2" style="gap:24px"><div><div class="small muted mb">Struktura stroškov (projekti s podatki o stroških v programu)</div>${rpDonut(all.parts)}</div><div><div class="small muted mb">Obračunano in stroški po projektih</div>${rpBars(D)}</div></div><div class="small muted mt">* stroški ocenjeni iz izida, ker objekt v programu nima vseh podatkov.</div></div>
 <h2>Po vodjih projektov</h2>${vodBlocks}
 ${ponHead('rpsys','<h2 style="margin:0">Dosežene cene po sistemih, 2026</h2>')}${pHid('rpsys')?'':`<div class="panel mb"><div class="tw"><table class="t"><thead><tr><th>Sistem</th><th>Debelina</th><th>Plošče</th><th class="n">Cenik €/m²</th><th class="n">Doseženo €/m²</th><th class="n">Razlika</th><th class="n">Izvedeno m²</th><th>Objekti</th></tr></thead><tbody>${sysRows||'<tr><td colspan="8" class="muted">V situacijah še ni postavk s prepoznanim sistemom.</td></tr>'}</tbody></table></div><div class="pad small muted" style="padding-top:6px">Iz vseh situacij vodij projektov v programu in iz arhiva obračunov 2026 (17 projektov). Doseženo je povprečje, tehtano z izvedeno količino, po pogodbenem popustu. Postavke so ločene po sistemu, debelini stene in ploščah (GKB, GKB-I, GKF, GKF-I, Diamant). GKB je primerjana s stolpcem navadna, GKB-I z vlagoodporno, GKF in GKF-I z ognjevarno; za Diamant cenika ni. Sistem, debelino in plošče program prepozna iz opisa postavke (npr. »W112, deb. 12,5 cm, GKF«). Kjer plošče niso navedene, šteje GKB; kjer debelina ni navedena, primerja z najtanjšo izvedbo.</div></div>`}`;
}
